  ('00000000-0000-4000-8000-000000100002', '00000000-0000-4000-8000-000000010000', 1, 2, '第 1 集 · 片段 01', '校园生活短片段，适合做精听、逐句循环和跟读练习。', '/api/mock-media/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_mp4/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_01.mp4', 321, 'published'),
