  ('00000000-0000-4000-8000-000000100004', '00000000-0000-4000-8000-000000010000', 1, 4, '第 1 集 · 片段 03', '校园生活短片段，适合做精听、逐句循环和跟读练习。', '/api/mock-media/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_mp4/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_03.mp4', 328, 'published'),
  ('00000000-0000-4000-8000-000000100005', '00000000-0000-4000-8000-000000010000', 1, 5, '第 1 集 · 片段 04', '校园生活短片段，适合做精听、逐句循环和跟读练习。', '/api/mock-media/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_mp4/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_04.mp4', 329, 'published'),
  ('00000000-0000-4000-8000-000000100006', '00000000-0000-4000-8000-000000010000', 1, 6, '第 1 集 · 片段 05', '校园生活短片段，适合做精听、逐句循环和跟读练习。', '/api/mock-media/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_mp4/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_05.mp4', 325, 'published'),
  ('00000000-0000-4000-8000-000000100007', '00000000-0000-4000-8000-000000010000', 1, 7, '第 1 集 · 片段 06', '校园生活短片段，适合做精听、逐句循环和跟读练习。', '/api/mock-media/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_mp4/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_06.mp4', 329, 'published'),
  ('00000000-0000-4000-8000-000000100008', '00000000-0000-4000-8000-000000010000', 1, 8, '第 1 集 · 片段 07', '校园生活短片段，适合做精听、逐句循环和跟读练习。', '/api/mock-media/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_mp4/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_07.mp4', 329, 'published'),
  ('00000000-0000-4000-8000-000000100009', '00000000-0000-4000-8000-000000010000', 1, 9, '第 1 集 · 片段 08', '校园生活短片段，适合做精听、逐句循环和跟读练习。', '/api/mock-media/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_mp4/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_08.mp4', 329, 'published'),
  ('00000000-0000-4000-8000-000000100010', '00000000-0000-4000-8000-000000010000', 1, 10, '第 1 集 · 片段 09', '校园生活短片段，适合做精听、逐句循环和跟读练习。', '/api/mock-media/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_mp4/%E6%A0%A1%E5%9B%AD%E4%B9%8B%E5%A4%96%E7%AC%AC%E4%B8%80%E5%AD%A3_%E7%AC%AC1%E9%9B%86_09.mp4', 276, 'published')
insert into public.subtitle_lines (id, episode_id, line_index, start_ms, end_ms, english_text, chinese_text, difficulty, keywords)
values
  ('00000000-0000-4000-8000-000000200001', '00000000-0000-4000-8000-000000100001', 1, 41640, 43940, 'We''ll be right back.', '我们马上回来。', 'B1', array['we''ll', 'right', 'back']::text[]),
  ('00000000-0000-4000-8000-000000200002', '00000000-0000-4000-8000-000000100001', 2, 60820, 62100, 'I''m sure of that.', '这一点我很确定。', 'B1', array['sure']::text[]),
  ('00000000-0000-4000-8000-000000200003', '00000000-0000-4000-8000-000000100001', 3, 100700, 102900, 'Thank you.', '谢谢。', 'B1', array['thank']::text[]),
  ('00000000-0000-4000-8000-000000200004', '00000000-0000-4000-8000-000000100001', 4, 122380, 123660, 'You looking for someone?', '你在找人吗？', 'B1', array['looking', 'someone']::text[]),
  ('00000000-0000-4000-8000-000000200005', '00000000-0000-4000-8000-000000100001', 5, 124000, 124720, 'Fuck, no.', '操，没有。', 'B1', array['fuck']::text[]),
  ('00000000-0000-4000-8000-000000200006', '00000000-0000-4000-8000-000000100001', 6, 125660, 126340, 'Sorry.', '抱歉。', 'B1', array['sorry']::text[]),
  ('00000000-0000-4000-8000-000000200007', '00000000-0000-4000-8000-000000100001', 7, 150000, 153260, 'In my class, average actually means average.', '在我的课上，"平均"就是字面意义上的平均。', 'B1', array['class', 'average', 'actually', 'means']::text[]),
  ('00000000-0000-4000-8000-000000200008', '00000000-0000-4000-8000-000000100001', 8, 153680, 156980, 'That is why 70% of you got a C plus or lower.', '所以你们当中百分之七十的人只拿到了 C+ 或更低。', 'B1', array['plus', 'lower']::text[]),
  ('00000000-0000-4000-8000-000000200009', '00000000-0000-4000-8000-000000100001', 9, 157220, 158940, 'It''s a fucking jock class.', '这就是门混给运动员的破课。', 'B1', array['it''s', 'fucking', 'jock', 'class']::text[]),
  ('00000000-0000-4000-8000-000000200010', '00000000-0000-4000-8000-000000100001', 10, 159040, 160500, 'Like, why am I being forced to try?', '凭什么逼我这么拼？', 'B1', array['like', 'being', 'forced']::text[]),
  ('00000000-0000-4000-8000-000000200011', '00000000-0000-4000-8000-000000100001', 11, 160740, 161480, 'I probably failed.', '我大概挂了。', 'B1', array['probably', 'failed']::text[]),
  ('00000000-0000-4000-8000-000000200012', '00000000-0000-4000-8000-000000100001', 12, 161740, 162440, 'Oh, I definitely did.', '哦，我绝对挂了。', 'B1', array['definitely']::text[]),
  ('00000000-0000-4000-8000-000000200013', '00000000-0000-4000-8000-000000100001', 13, 163080, 164600, 'Do you think we can still drop it, bro?', '你觉得我们现在还退得了课吗，兄弟？', 'B1', array['think', 'still', 'drop']::text[]),
  ('00000000-0000-4000-8000-000000200014', '00000000-0000-4000-8000-000000100001', 14, 165620, 166480, 'I can''t.', '我不行。', 'B1', array['can''t']::text[]),
  ('00000000-0000-4000-8000-000000200015', '00000000-0000-4000-8000-000000100001', 15, 166580, 167900, 'I need this for my major.', '我的专业需要这门课。', 'B1', array['need', 'major']::text[]),
  ('00000000-0000-4000-8000-000000200016', '00000000-0000-4000-8000-000000100001', 16, 168220, 168700, 'Relax.', '放轻松。', 'B1', array['relax']::text[]),
  ('00000000-0000-4000-8000-000000200017', '00000000-0000-4000-8000-000000100001', 17, 169160, 172760, 'Sure, your coach will convince Tolbert to get creative with your grading system.', '没事，你的教练会说服托尔伯特给你的评分动点脑筋。', 'B1', array['sure', 'coach', 'will', 'convince', 'tolbert', 'creative']::text[]),
  ('00000000-0000-4000-8000-000000200018', '00000000-0000-4000-8000-000000100001', 18, 174340, 174820, 'Jocks.', '运动员们。', 'B1', array['jocks']::text[]),
  ('00000000-0000-4000-8000-000000200019', '00000000-0000-4000-8000-000000100001', 19, 175300, 176080, 'So pretty.', '那么好看。', 'B1', array['pretty']::text[]),
  ('00000000-0000-4000-8000-000000200020', '00000000-0000-4000-8000-000000100001', 20, 177040, 178000, 'So entitled.', '那么自以为是。', 'B1', array['entitled']::text[]),
  ('00000000-0000-4000-8000-000000200021', '00000000-0000-4000-8000-000000100001', 21, 180140, 182360, 'Babe, I''m trying to be below one of those stereotypes.', '宝贝，我可不想被归进那些刻板印象里。', 'B1', array['babe', 'trying', 'below', 'those', 'stereotypes']::text[]),
  ('00000000-0000-4000-8000-000000200022', '00000000-0000-4000-8000-000000100001', 22, 184180, 185180, 'Maybe behind.', '也许是落在后面吧。', 'B1', array['maybe', 'behind']::text[]),
  ('00000000-0000-4000-8000-000000200023', '00000000-0000-4000-8000-000000100001', 23, 186120, 189220, 'And none of you star athletes should expect any special treatment.', '还有，你们这些明星运动员谁也别指望有什么特殊待遇。', 'B1', array['none', 'star', 'athletes', 'should', 'expect', 'special']::text[]),
  ('00000000-0000-4000-8000-000000200024', '00000000-0000-4000-8000-000000100001', 24, 189320, 193180, 'You knew what your practice schedule looked like before you signed up for this class, Mr. Maxwell.', '报名这门课之前，你早就知道自己的训练日程是什么样，麦克斯韦尔先生。', 'B1', array['knew', 'what', 'practice', 'schedule', 'looked', 'like']::text[]),
  ('00000000-0000-4000-8000-000000200025', '00000000-0000-4000-8000-000000100001', 25, 193620, 198880, 'Me? No, I was just curious about extra credit opportunities to, you know, learn more.', '我？不，我只是好奇有没有加分的机会，你懂的，多学点东西。', 'B1', array['just', 'curious', 'about', 'extra', 'credit', 'opportunities']::text[]),
  ('00000000-0000-4000-8000-000000200026', '00000000-0000-4000-8000-000000100001', 26, 199020, 201000, 'You can learn from your next assignment.', '你可以从下一份作业里好好学。', 'B1', array['learn', 'from', 'next', 'assignment']::text[]),
  ('00000000-0000-4000-8000-000000200027', '00000000-0000-4000-8000-000000100001', 27, 201400, 202280, 'Oral presentations.', '口头演讲。', 'B1', array['oral', 'presentations']::text[]),
  ('00000000-0000-4000-8000-000000200028', '00000000-0000-4000-8000-000000100001', 28, 203660, 206080, 'Okay. Yeah, definitely dropping.', '好吧。嗯，那绝对要退课了。', 'B1', array['okay', 'yeah', 'definitely', 'dropping']::text[]),
  ('00000000-0000-4000-8000-000000200029', '00000000-0000-4000-8000-000000100001', 29, 206080, 206680, 'Hey.', '嘿。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200030', '00000000-0000-4000-8000-000000100001', 30, 207800, 208200, 'Thanks.', '谢了。', 'B1', array['thanks']::text[]),
  ('00000000-0000-4000-8000-000000200031', '00000000-0000-4000-8000-000000100001', 31, 208940, 209340, 'Perfect.', '完美。', 'B1', array['perfect']::text[]),
  ('00000000-0000-4000-8000-000000200032', '00000000-0000-4000-8000-000000100001', 32, 209880, 213000, 'Another D. So, how''d you do?', '又一个 D。那，你考得怎么样？', 'B1', array['another', 'how''d']::text[]),
  ('00000000-0000-4000-8000-000000200033', '00000000-0000-4000-8000-000000100001', 33, 214440, 215040, 'No, I''m good.', '不用了，我没事。', 'B1', array['good']::text[]),
  ('00000000-0000-4000-8000-000000200034', '00000000-0000-4000-8000-000000100001', 34, 215400, 215800, 'Girl.', '姐妹。', 'B1', array['girl']::text[]),
  ('00000000-0000-4000-8000-000000200035', '00000000-0000-4000-8000-000000100001', 35, 216240, 216640, 'Really?', '真的吗？', 'B1', array['really']::text[]),
  ('00000000-0000-4000-8000-000000200036', '00000000-0000-4000-8000-000000100001', 36, 217600, 218000, 'Yeah.', '嗯。', 'B1', array['yeah']::text[]),
  ('00000000-0000-4000-8000-000000200037', '00000000-0000-4000-8000-000000100001', 37, 218120, 219840, 'I-I-I wrote in like an hour or so.', '我大概花了一个小时左右就写完了。', 'B1', array['wrote', 'like', 'hour']::text[]),
  ('00000000-0000-4000-8000-000000200038', '00000000-0000-4000-8000-000000100001', 38, 222240, 223620, 'Fucking hell, you aced it?', '我的天，你拿了满分？', 'B1', array['fucking', 'hell', 'aced']::text[]),
  ('00000000-0000-4000-8000-000000200039', '00000000-0000-4000-8000-000000100001', 39, 223840, 224800, 'I knew it.', '我就知道。', 'B1', array['knew']::text[]),
  ('00000000-0000-4000-8000-000000200040', '00000000-0000-4000-8000-000000100001', 40, 224840, 225160, 'Show me.', '给我看看。', 'B1', array['show']::text[]),
  ('00000000-0000-4000-8000-000000200041', '00000000-0000-4000-8000-000000100001', 41, 226020, 226740, 'Do you mind?', '你介意吗？', 'B1', array['mind']::text[]),
  ('00000000-0000-4000-8000-000000200042', '00000000-0000-4000-8000-000000100001', 42, 227100, 227480, 'What?', '什么？', 'B1', array['what']::text[]),
  ('00000000-0000-4000-8000-000000200043', '00000000-0000-4000-8000-000000100001', 43, 228880, 230640, 'Only you get to look at things you shouldn''t?', '只许你看不该看的东西？', 'B1', array['only', 'look', 'things', 'shouldn''t']::text[]),
  ('00000000-0000-4000-8000-000000200044', '00000000-0000-4000-8000-000000100001', 44, 231540, 231940, 'Okay.', '好吧。', 'B1', array['okay']::text[]),
  ('00000000-0000-4000-8000-000000200045', '00000000-0000-4000-8000-000000100001', 45, 232360, 236060, 'Now that we got that covered, anybody want to hazard a guess as to what we will be discussing?', '既然这个问题说清楚了，有没有人愿意猜一猜我们接下来要讨论什么？', 'B1', array['covered', 'anybody', 'want', 'hazard', 'guess', 'what']::text[]),
  ('00000000-0000-4000-8000-000000200046', '00000000-0000-4000-8000-000000100001', 46, 241840, 243520, 'Here goes your manic pixie dream boy.', '你的"梦中情男"来了。', 'B1', array['here', 'goes', 'manic', 'pixie', 'dream']::text[]),
  ('00000000-0000-4000-8000-000000200047', '00000000-0000-4000-8000-000000100001', 47, 243680, 243940, 'Stop.', '别说了。', 'B1', array['stop']::text[]),
  ('00000000-0000-4000-8000-000000200048', '00000000-0000-4000-8000-000000100001', 48, 244100, 245620, 'Justin Cole''s not my anything.', '贾斯汀·科尔跟我没有任何关系。', 'B1', array['justin', 'cole''s', 'anything']::text[]),
  ('00000000-0000-4000-8000-000000200049', '00000000-0000-4000-8000-000000100001', 49, 245940, 246680, 'It''s not too late.', '现在还不晚。', 'B1', array['it''s', 'late']::text[]),
  ('00000000-0000-4000-8000-000000200050', '00000000-0000-4000-8000-000000100001', 50, 247500, 248540, 'It''s not too late.', '现在还不晚。', 'B1', array['it''s', 'late']::text[]),
  ('00000000-0000-4000-8000-000000200051', '00000000-0000-4000-8000-000000100001', 51, 249180, 250640, 'You are intolerable.', '你真让人受不了。', 'B1', array['intolerable']::text[]),
  ('00000000-0000-4000-8000-000000200052', '00000000-0000-4000-8000-000000100001', 52, 250960, 251720, 'Did she do it?', '她做了吗？', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200053', '00000000-0000-4000-8000-000000100001', 53, 251800, 252720, 'Did she talk to Justin Cole?', '她跟贾斯汀·科尔搭话了吗？', 'B1', array['talk', 'justin', 'cole']::text[]),
  ('00000000-0000-4000-8000-000000200054', '00000000-0000-4000-8000-000000100001', 54, 252860, 253660, 'No, no.', '没有，没有。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200055', '00000000-0000-4000-8000-000000100001', 55, 253700, 255660, 'She''s too busy pining wistfully from afar.', '她忙着在远处一脸惆怅地暗恋呢。', 'B1', array['she''s', 'busy', 'pining', 'wistfully', 'from', 'afar']::text[]),
  ('00000000-0000-4000-8000-000000200056', '00000000-0000-4000-8000-000000100001', 56, 256000, 257800, 'He has literally no idea who I am, okay?', '他根本不知道我是谁，好吗？', 'B1', array['literally', 'idea', 'okay']::text[]),
  ('00000000-0000-4000-8000-000000200057', '00000000-0000-4000-8000-000000100001', 57, 257880, 259300, 'Am I supposed to just fling myself at him?', '难道要我直接扑上去吗？', 'B1', array['supposed', 'just', 'fling', 'myself']::text[]),
  ('00000000-0000-4000-8000-000000200058', '00000000-0000-4000-8000-000000100001', 58, 259440, 259700, 'Yes.', '对。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200059', '00000000-0000-4000-8000-000000100001', 59, 260140, 260400, 'Mona!', '莫娜！', 'B1', array['mona']::text[]),
  ('00000000-0000-4000-8000-000000200060', '00000000-0000-4000-8000-000000100001', 60, 260620, 262160, 'I''ve said maybe two words to the guy,', '我跟那家伙顶多说过两个字，', 'B1', array['i''ve', 'said', 'maybe', 'words']::text[]),
  ('00000000-0000-4000-8000-000000200061', '00000000-0000-4000-8000-000000100001', 61, 262240, 263500, 'and they weren''t even good words.', '而且还不是什么好话。', 'B1', array['they', 'weren''t', 'even', 'good', 'words']::text[]),
  ('00000000-0000-4000-8000-000000200062', '00000000-0000-4000-8000-000000100001', 62, 263660, 264780, 'Hannah, you love his music,', '汉娜，你那么喜欢他的音乐，', 'B1', array['hannah', 'love', 'music']::text[]),
  ('00000000-0000-4000-8000-000000200063', '00000000-0000-4000-8000-000000100001', 63, 264800, 266040, 'and you''ve been crushing on him for weeks.', '而且你都暗恋他好几个星期了。', 'B1', array['you''ve', 'been', 'crushing', 'weeks']::text[]),
  ('00000000-0000-4000-8000-000000200064', '00000000-0000-4000-8000-000000100001', 64, 266300, 266500, 'Mona!', '莫娜！', 'B1', array['mona']::text[]),
  ('00000000-0000-4000-8000-000000200065', '00000000-0000-4000-8000-000000100001', 65, 267080, 274680, 'Five, you''re on at nine. Okay. Eight words ever. Hey, Mona. Who''s Mona? I think you—', '五分钟……你九点上场。好。这辈子总共说了八个字。嘿，莫娜。谁是莫娜？我觉得你……', 'B1', array['five', 'you''re', 'nine', 'okay', 'eight', 'words']::text[]),
  ('00000000-0000-4000-8000-000000200066', '00000000-0000-4000-8000-000000100001', 66, 277140, 283100, 'I''m not Mona. It is an M though, right? Not even close. What do you want, Garrett Graham?', '我不是莫娜。不过是 M 开头的，对吧？差远了。你想要什么，加勒特·格雷厄姆？', 'B1', array['mona', 'though', 'right', 'even', 'close', 'what']::text[]),
  ('00000000-0000-4000-8000-000000200067', '00000000-0000-4000-8000-000000100001', 67, 283100, 287700, 'Petals to walk on? Maybe another fancy gym that costs thousands of dollars, even though', '铺花瓣给你走？也许再来一座花好几千美元的豪华健身房，', 'B1', array['petals', 'walk', 'maybe', 'another', 'fancy', 'costs']::text[]),
  ('00000000-0000-4000-8000-000000200068', '00000000-0000-4000-8000-000000100001', 68, 287700, 294400, 'the theater department is literally falling apart. So, uh, I failed that paper. Sounds like a lot of—', '尽管戏剧系都快垮了。呃，我那篇论文挂了。听起来麻烦不少。', 'B1', array['theater', 'department', 'literally', 'falling', 'apart', 'failed']::text[]),
  ('00000000-0000-4000-8000-000000200069', '00000000-0000-4000-8000-000000100001', 69, 294400, 298000, 'And I was thinking it''d be great if I didn''t fail again.', '我在想，要是我下次别再挂科就好了。', 'B1', array['thinking', 'it''d', 'great', 'didn''t', 'fail', 'again']::text[]),
  ('00000000-0000-4000-8000-000000200070', '00000000-0000-4000-8000-000000100001', 70, 299520, 299960, 'So...', '所以……', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200071', '00000000-0000-4000-8000-000000100001', 71, 301100, 302260, 'Was there a question in there?', '你这话里有问题要问吗？', 'B1', array['there', 'question']::text[]),
  ('00000000-0000-4000-8000-000000200072', '00000000-0000-4000-8000-000000100001', 72, 302280, 302840, 'There was a question.', '是有个问题。', 'B1', array['there', 'question']::text[]),
  ('00000000-0000-4000-8000-000000200073', '00000000-0000-4000-8000-000000100001', 73, 303220, 305120, 'I don''t think I heard a question, no.', '我没听到什么问题，没有。', 'B1', array['don''t', 'think', 'heard', 'question']::text[]),
  ('00000000-0000-4000-8000-000000200074', '00000000-0000-4000-8000-000000100001', 74, 305440, 307000, 'You guys are late for scene study.', '你们俩排练场景分析课要迟到了。', 'B1', array['guys', 'late', 'scene', 'study']::text[]),
  ('00000000-0000-4000-8000-000000200075', '00000000-0000-4000-8000-000000100001', 75, 307200, 308440, 'All right, go. I''ll see you at dinner.', '好了，去吧。晚饭见。', 'B1', array['right', 'i''ll', 'dinner']::text[]),
  ('00000000-0000-4000-8000-000000200076', '00000000-0000-4000-8000-000000100001', 76, 309480, 310220, 'Bye, Mona.', '再见，莫娜。', 'B1', array['mona']::text[]),
  ('00000000-0000-4000-8000-000000200077', '00000000-0000-4000-8000-000000100001', 77, 311480, 312620, 'I need your help.', '我需要你帮忙。', 'B1', array['need', 'help']::text[]),
  ('00000000-0000-4000-8000-000000200078', '00000000-0000-4000-8000-000000100001', 78, 313640, 314080, 'Wow.', '哇哦。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200079', '00000000-0000-4000-8000-000000100001', 79, 314500, 314940, 'What?', '怎么了？', 'B1', array['what']::text[]),
  ('00000000-0000-4000-8000-000000200080', '00000000-0000-4000-8000-000000100001', 80, 315680, 318540, 'See, usually with questions, voices kind of go up at the end,', '你看，问问题的时候，语调通常会在结尾往上扬，', 'B1', array['usually', 'questions', 'voices', 'kind']::text[]),
  ('00000000-0000-4000-8000-000000200081', '00000000-0000-4000-8000-000000100001', 81, 318620, 320960, 'and your voice didn''t do that, so...', '而你的语调没有，所以……', 'B1', array['voice', 'didn''t']::text[]),
  ('00000000-0000-4000-8000-000000200082', '00000000-0000-4000-8000-000000100001', 82, 320960, 321300, 'Okay.', '好吧。', 'B1', array['okay']::text[]),
  ('00000000-0000-4000-8000-000000200083', '00000000-0000-4000-8000-000000100001', 83, 321300, 324760, 'Okay, could you, pretty please with sugar on top,', '好啦，能不能请你行行好、求求你了，', 'B1', array['okay', 'could', 'pretty', 'please', 'sugar']::text[]),
  ('00000000-0000-4000-8000-000000200084', '00000000-0000-4000-8000-000000100001', 84, 324920, 327160, 'help me study so that it don''t fail spectacularly?', '帮我复习，好让我别考得一塌糊涂？', 'B1', array['help', 'study', 'don''t', 'fail', 'spectacularly']::text[]),
  ('00000000-0000-4000-8000-000000200085', '00000000-0000-4000-8000-000000100001', 85, 327320, 327680, 'Better.', '这还差不多。', 'B1', array['better']::text[]),
  ('00000000-0000-4000-8000-000000200086', '00000000-0000-4000-8000-000000100002', 1, 0, 420, 'But no.', '但是不行。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200087', '00000000-0000-4000-8000-000000100002', 2, 1800, 2360, 'Come on.', '拜托嘛。', 'B1', array['come']::text[]),
  ('00000000-0000-4000-8000-000000200088', '00000000-0000-4000-8000-000000100002', 3, 2860, 3740, 'Do me a solid.', '帮我个忙。', 'B1', array['solid']::text[]),
  ('00000000-0000-4000-8000-000000200089', '00000000-0000-4000-8000-000000100002', 4, 3880, 5700, 'I mean, you kind of owe me for that sneak peek.', '我是说，上次那次"意外瞄到"，你也算欠我个人情。', 'B1', array['mean', 'kind', 'sneak', 'peek']::text[]),
  ('00000000-0000-4000-8000-000000200090', '00000000-0000-4000-8000-000000100002', 5, 5860, 7160, 'Kate, that was an honest mistake.', '凯特，那纯属无心之失。', 'B1', array['kate', 'honest', 'mistake']::text[]),
  ('00000000-0000-4000-8000-000000200091', '00000000-0000-4000-8000-000000100002', 6, 7560, 8020, 'Was it?', '是吗？', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200092', '00000000-0000-4000-8000-000000100002', 7, 8140, 10160, 'I mean, tons of girls would have paid good money', '我是说，一大堆女生可是愿意花大价钱', 'B1', array['mean', 'tons', 'girls', 'would', 'have', 'paid']::text[]),
  ('00000000-0000-4000-8000-000000200093', '00000000-0000-4000-8000-000000100002', 8, 10160, 11220, 'for the view you got, so.', '来看你看到的那一幕呢。', 'B1', array['view']::text[]),
  ('00000000-0000-4000-8000-000000200094', '00000000-0000-4000-8000-000000100002', 9, 11420, 12380, 'OK, I''m scarred for life.', '得了吧，我都留下一辈子的心理阴影了。', 'B1', array['scarred', 'life']::text[]),
  ('00000000-0000-4000-8000-000000200095', '00000000-0000-4000-8000-000000100002', 10, 12520, 13540, 'If anything, you owe me.', '真要说，是你欠我。', 'B1', array['anything']::text[]),
  ('00000000-0000-4000-8000-000000200096', '00000000-0000-4000-8000-000000100002', 11, 13840, 17180, 'Well, I have to ace the oral presentation or I can''t play.', '听着，我必须把口头演讲拿到高分，不然就不能上场打球。', 'B1', array['well', 'have', 'oral', 'presentation', 'can''t', 'play']::text[]),
  ('00000000-0000-4000-8000-000000200097', '00000000-0000-4000-8000-000000100002', 12, 17400, 19340, 'OK, believe it or not, I have my own priorities', '好吧，信不信由你，我也有我自己的事要忙，', 'B1', array['believe', 'have', 'priorities']::text[]),
  ('00000000-0000-4000-8000-000000200098', '00000000-0000-4000-8000-000000100002', 13, 19340, 20740, 'that have nothing to do with bar hockey.', '跟你那破冰球一点关系都没有。', 'B1', array['have', 'nothing', 'hockey']::text[]),
  ('00000000-0000-4000-8000-000000200099', '00000000-0000-4000-8000-000000100002', 14, 21020, 22220, 'Find another tutor, dude.', '另找个家教吧，哥们。', 'B1', array['find', 'another', 'tutor', 'dude']::text[]),
  ('00000000-0000-4000-8000-000000200100', '00000000-0000-4000-8000-000000100002', 15, 27380, 29160, 'Turns out I''m still 20', '原来我还只是个二十岁的人，', 'B1', array['turns', 'still']::text[]),
  ('00000000-0000-4000-8000-000000200101', '00000000-0000-4000-8000-000000100002', 16, 30000, 31480, 'I''m acting middle-aged.', '却活得像个中年人。', 'B1', array['acting', 'middle', 'aged']::text[]),
  ('00000000-0000-4000-8000-000000200102', '00000000-0000-4000-8000-000000100002', 17, 32000, 33780, 'Same old conversation.', '还是那套老掉牙的对话。', 'B1', array['same', 'conversation']::text[]),
  ('00000000-0000-4000-8000-000000200103', '00000000-0000-4000-8000-000000100002', 18, 34290, 36240, 'All this small talk that I hate.', '都是我讨厌的那些客套寒暄。', 'B1', array['small', 'talk', 'hate']::text[]),
  ('00000000-0000-4000-8000-000000200104', '00000000-0000-4000-8000-000000100002', 19, 36840, 39220, 'And I never thought I''d say it.', '我从没想过自己会说出这种话，', 'B1', array['never', 'thought']::text[]),
  ('00000000-0000-4000-8000-000000200105', '00000000-0000-4000-8000-000000100002', 20, 39300, 40920, 'But I''m sick of everyone.', '但我真受够所有人了。', 'B1', array['sick', 'everyone']::text[]),
  ('00000000-0000-4000-8000-000000200106', '00000000-0000-4000-8000-000000100002', 21, 41500, 43580, 'I need to sweat it out.', '我得好好出身汗发泄一下。', 'B1', array['need', 'sweat']::text[]),
  ('00000000-0000-4000-8000-000000200107', '00000000-0000-4000-8000-000000100002', 22, 43800, 45980, 'I need to have some fun.', '我得找点乐子。', 'B1', array['need', 'have', 'some']::text[]),
  ('00000000-0000-4000-8000-000000200108', '00000000-0000-4000-8000-000000100002', 23, 46660, 49460, 'Get the cards and the cards and the cards and the cards.', '来发牌，发牌，一直发牌。', 'B1', array['cards']::text[]),
  ('00000000-0000-4000-8000-000000200109', '00000000-0000-4000-8000-000000100002', 24, 49900, 51900, 'And the dance and the boys and the boys.', '还有舞步，还有男孩们，男孩们。', 'B1', array['dance', 'boys']::text[]),
  ('00000000-0000-4000-8000-000000200110', '00000000-0000-4000-8000-000000100002', 25, 52260, 53500, 'With their lips.', '带着他们的唇。', 'B1', array['their', 'lips']::text[]),
  ('00000000-0000-4000-8000-000000200111', '00000000-0000-4000-8000-000000100002', 26, 53760, 57320, 'Wishing they had their big boy hands all on my lips.', '盼着用他们那双大手抚上我的唇。', 'B1', array['wishing', 'they', 'their', 'hands', 'lips']::text[]),
  ('00000000-0000-4000-8000-000000200112', '00000000-0000-4000-8000-000000100002', 27, 57700, 59140, 'Everybody''s on some drugs.', '每个人都嗑得飘飘然。', 'B1', array['everybody''s', 'some', 'drugs']::text[]),
  ('00000000-0000-4000-8000-000000200113', '00000000-0000-4000-8000-000000100002', 28, 67380, 68740, 'Oh, shit.', '哦，糟了。', 'B1', array['shit']::text[]),
  ('00000000-0000-4000-8000-000000200114', '00000000-0000-4000-8000-000000100002', 29, 101560, 103640, 'Hey. Wanted to talk to me?', '嘿，你想找我谈谈？', 'B1', array['wanted', 'talk']::text[]),
  ('00000000-0000-4000-8000-000000200115', '00000000-0000-4000-8000-000000100002', 30, 103840, 107040, 'If this is about being late, I have a new idea for a shortcut.', '如果是为了我迟到的事，我有个抄近路的新主意。', 'B1', array['about', 'being', 'late', 'have', 'idea', 'shortcut']::text[]),
  ('00000000-0000-4000-8000-000000200116', '00000000-0000-4000-8000-000000100002', 31, 111020, 113440, 'Oh. Oh, you have your bad news face.', '哦。哦，你一脸要说坏消息的表情。', 'B1', array['have', 'news', 'face']::text[]),
  ('00000000-0000-4000-8000-000000200117', '00000000-0000-4000-8000-000000100002', 32, 115380, 116280, 'It''s your scholarship.', '是你的奖学金。', 'B1', array['it''s', 'scholarship']::text[]),
  ('00000000-0000-4000-8000-000000200118', '00000000-0000-4000-8000-000000100002', 33, 118080, 119440, 'It''s not happening this year.', '今年没了。', 'B1', array['it''s', 'happening', 'year']::text[]),
  ('00000000-0000-4000-8000-000000200119', '00000000-0000-4000-8000-000000100002', 34, 120040, 120480, 'What?', '什么？', 'B1', array['what']::text[]),
  ('00000000-0000-4000-8000-000000200120', '00000000-0000-4000-8000-000000100002', 35, 120900, 123520, 'Budget cuts don''t even get me started.', '预算削减，这事别提了，一提就来气。', 'B1', array['budget', 'cuts', 'don''t', 'even', 'started']::text[]),
  ('00000000-0000-4000-8000-000000200121', '00000000-0000-4000-8000-000000100002', 36, 123640, 125540, 'No, we''re three weeks into the semester.', '不，我们这学期都已经过了三周了。', 'B1', array['we''re', 'three', 'weeks', 'into', 'semester']::text[]),
  ('00000000-0000-4000-8000-000000200122', '00000000-0000-4000-8000-000000100002', 37, 125740, 128560, 'How can... No, no, they can''t. No.', '怎么能……不，不行，他们不能这样。不。', 'B1', array['they', 'can''t']::text[]),
  ('00000000-0000-4000-8000-000000200123', '00000000-0000-4000-8000-000000100002', 38, 128820, 130440, 'We''ll get you an appointment with the financial aid office.', '我们给你约一次助学金办公室的面谈。', 'B1', array['we''ll', 'appointment', 'financial', 'office']::text[]),
  ('00000000-0000-4000-8000-000000200124', '00000000-0000-4000-8000-000000100002', 39, 131020, 131860, 'They can help.', '他们能帮上忙。', 'B1', array['they', 'help']::text[]),
  ('00000000-0000-4000-8000-000000200125', '00000000-0000-4000-8000-000000100002', 40, 132220, 134180, 'No, they''re just gonna give me another work-study job.', '不，他们只会再给我安排一份勤工俭学的活儿。', 'B1', array['they''re', 'just', 'gonna', 'give', 'another', 'work']::text[]),
  ('00000000-0000-4000-8000-000000200126', '00000000-0000-4000-8000-000000100002', 41, 134240, 136600, 'I can barely do all my schoolwork as it is.', '我现在光是应付功课都快忙不过来了。', 'B1', array['barely', 'schoolwork']::text[]),
  ('00000000-0000-4000-8000-000000200127', '00000000-0000-4000-8000-000000100002', 42, 138080, 138840, 'Oh, my God.', '我的天哪。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200128', '00000000-0000-4000-8000-000000100002', 43, 139140, 140400, 'Okay, whoa, whoa, whoa, whoa, whoa, whoa.', '好了，喂喂喂喂喂喂。', 'B1', array['okay', 'whoa']::text[]),
  ('00000000-0000-4000-8000-000000200129', '00000000-0000-4000-8000-000000100002', 44, 140420, 141420, 'Don''t stop breathing.', '别忘了呼吸。', 'B1', array['don''t', 'stop', 'breathing']::text[]),
  ('00000000-0000-4000-8000-000000200130', '00000000-0000-4000-8000-000000100002', 45, 141560, 144560, 'You need air to process and live.', '你需要空气来理清思绪、活下去。', 'B1', array['need', 'process', 'live']::text[]),
  ('00000000-0000-4000-8000-000000200131', '00000000-0000-4000-8000-000000100002', 46, 144940, 146200, 'Yeah, I also need money.', '是啊，我还需要钱。', 'B1', array['yeah', 'also', 'need', 'money']::text[]),
  ('00000000-0000-4000-8000-000000200132', '00000000-0000-4000-8000-000000100002', 47, 146880, 149000, 'Is there another scholarship I could apply for?', '还有别的奖学金我可以申请吗？', 'B1', array['there', 'another', 'scholarship', 'could', 'apply']::text[]),
  ('00000000-0000-4000-8000-000000200133', '00000000-0000-4000-8000-000000100002', 48, 150460, 151420, 'Composition scholarship?', '作曲奖学金？', 'B1', array['composition', 'scholarship']::text[]),
  ('00000000-0000-4000-8000-000000200134', '00000000-0000-4000-8000-000000100002', 49, 154240, 156020, 'I could switch concentrations.', '我可以换个主修方向。', 'B1', array['could', 'switch', 'concentrations']::text[]),
  ('00000000-0000-4000-8000-000000200135', '00000000-0000-4000-8000-000000100002', 50, 156280, 156740, 'Performance?', '表演？', 'B1', array['performance']::text[]),
  ('00000000-0000-4000-8000-000000200136', '00000000-0000-4000-8000-000000100002', 51, 157120, 159300, 'Girl, we both know you''re a much stronger composer', '姑娘，我们都清楚，比起单簧管演奏，', 'B1', array['girl', 'both', 'know', 'you''re', 'much', 'stronger']::text[]),
  ('00000000-0000-4000-8000-000000200137', '00000000-0000-4000-8000-000000100002', 52, 159300, 160140, 'than clarinetist.', '你作曲要强得多。', 'B1', array['than', 'clarinetist']::text[]),
  ('00000000-0000-4000-8000-000000200138', '00000000-0000-4000-8000-000000100002', 53, 160320, 162140, 'And there''s no money in classical.', '而且古典乐根本不赚钱。', 'B1', array['there''s', 'money', 'classical']::text[]),
  ('00000000-0000-4000-8000-000000200139', '00000000-0000-4000-8000-000000100002', 54, 162480, 163800, 'Well, jazz. Jazz.', '那，爵士。爵士。', 'B1', array['well', 'jazz']::text[]),
  ('00000000-0000-4000-8000-000000200140', '00000000-0000-4000-8000-000000100002', 55, 163900, 164880, 'I could write jazz.', '我可以写爵士乐。', 'B1', array['could', 'write', 'jazz']::text[]),
  ('00000000-0000-4000-8000-000000200141', '00000000-0000-4000-8000-000000100002', 56, 165700, 167180, 'Even less money.', '那更不赚钱。', 'B1', array['even', 'less', 'money']::text[]),
  ('00000000-0000-4000-8000-000000200142', '00000000-0000-4000-8000-000000100002', 57, 167340, 167660, 'Right.', '也对。', 'B1', array['right']::text[]),
  ('00000000-0000-4000-8000-000000200143', '00000000-0000-4000-8000-000000100002', 58, 168220, 169380, 'What do I do?', '那我该怎么办？', 'B1', array['what']::text[]),
  ('00000000-0000-4000-8000-000000200144', '00000000-0000-4000-8000-000000100002', 59, 169760, 171500, 'Let''s chat again on Monday', '我们周一再聊吧，', 'B1', array['let''s', 'chat', 'again', 'monday']::text[]),
  ('00000000-0000-4000-8000-000000200145', '00000000-0000-4000-8000-000000100002', 60, 171500, 173040, 'after you''ve had a few days to sit with this.', '等你有几天时间消化一下这件事。', 'B1', array['after', 'you''ve', 'days']::text[]),
  ('00000000-0000-4000-8000-000000200146', '00000000-0000-4000-8000-000000100002', 61, 173300, 173940, 'Hey, Hannah.', '嘿，汉娜。', 'B1', array['hannah']::text[]),
  ('00000000-0000-4000-8000-000000200147', '00000000-0000-4000-8000-000000100002', 62, 175080, 176840, 'We''re gonna get through it, okay?', '我们会挺过去的，好吗？', 'B1', array['we''re', 'gonna', 'through', 'okay']::text[]),
  ('00000000-0000-4000-8000-000000200148', '00000000-0000-4000-8000-000000100002', 63, 181680, 182920, 'I could write pop.', '我可以写流行乐。', 'B1', array['could', 'write']::text[]),
  ('00000000-0000-4000-8000-000000200149', '00000000-0000-4000-8000-000000100002', 64, 183340, 185240, 'First place comes with a scholarship, right?', '第一名会有奖学金，对吧？', 'B1', array['first', 'place', 'comes', 'scholarship', 'right']::text[]),
  ('00000000-0000-4000-8000-000000200150', '00000000-0000-4000-8000-000000100002', 65, 185560, 186520, 'Right, but...', '对，但是……', 'B1', array['right']::text[]),
  ('00000000-0000-4000-8000-000000200151', '00000000-0000-4000-8000-000000100002', 66, 186520, 189120, 'You just said that I''m a stronger composer than clarinetist.', '你刚才才说我作曲比演奏单簧管更强。', 'B1', array['just', 'said', 'stronger', 'composer', 'than', 'clarinetist']::text[]),
  ('00000000-0000-4000-8000-000000200152', '00000000-0000-4000-8000-000000100002', 67, 189240, 189800, 'Moments ago.', '就在刚刚。', 'B1', array['moments']::text[]),
  ('00000000-0000-4000-8000-000000200153', '00000000-0000-4000-8000-000000100002', 68, 189860, 193780, 'And I wrote an outstanding piece on pop harmonies', '而且我还写过一篇关于流行乐和声的出色作品，', 'B1', array['wrote', 'outstanding', 'piece', 'harmonies']::text[]),
  ('00000000-0000-4000-8000-000000200154', '00000000-0000-4000-8000-000000100002', 69, 193780, 195340, 'in your music theory class freshman year.', '就在大一你的乐理课上。', 'B1', array['music', 'theory', 'class', 'freshman', 'year']::text[]),
  ('00000000-0000-4000-8000-000000200155', '00000000-0000-4000-8000-000000100002', 70, 195460, 196680, 'I mean, you''re a word outstanding.', '我是说，"出色"这个词用得没错。', 'B1', array['mean', 'you''re', 'word', 'outstanding']::text[]),
  ('00000000-0000-4000-8000-000000200156', '00000000-0000-4000-8000-000000100002', 71, 197320, 198000, 'It''s true.', '是真的。', 'B1', array['it''s', 'true']::text[]),
