  ('00000000-0000-4000-8000-000000200387', '00000000-0000-4000-8000-000000100004', 71, 267620, 268960, 'House says...', '全屋表决……', 'B1', array['house', 'says']::text[]),
  ('00000000-0000-4000-8000-000000200388', '00000000-0000-4000-8000-000000100004', 72, 268960, 269740, 'Nay!', '反对！', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200389', '00000000-0000-4000-8000-000000100004', 73, 270220, 270620, 'Nay!', '反对！', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200390', '00000000-0000-4000-8000-000000100004', 74, 271260, 271660, 'Nay.', '反对。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200391', '00000000-0000-4000-8000-000000100004', 75, 271920, 275280, 'Okay, Dean agrees with you, which kind of just proves that you''re wrong.', '好吧，迪恩同意你的看法，而这恰恰证明了你是错的。', 'B1', array['okay', 'dean', 'agrees', 'which', 'kind', 'just']::text[]),
  ('00000000-0000-4000-8000-000000200392', '00000000-0000-4000-8000-000000100004', 76, 275400, 275760, 'Fuck.', '操。', 'B1', array['fuck']::text[]),
  ('00000000-0000-4000-8000-000000200393', '00000000-0000-4000-8000-000000100004', 77, 275760, 277700, 'You know, I don''t have to take this slander.', '跟你说，我没必要受这种污蔑。', 'B1', array['know', 'don''t', 'have', 'take', 'slander']::text[]),
  ('00000000-0000-4000-8000-000000200394', '00000000-0000-4000-8000-000000100004', 78, 277780, 280380, 'I''m a responsible, upstanding member of society.', '我可是个负责任、正直的社会一员。', 'B1', array['responsible', 'upstanding', 'member', 'society']::text[]),
  ('00000000-0000-4000-8000-000000200395', '00000000-0000-4000-8000-000000100004', 79, 280720, 281040, 'Dean.', '迪恩。', 'B1', array['dean']::text[]),
  ('00000000-0000-4000-8000-000000200396', '00000000-0000-4000-8000-000000100004', 80, 284420, 285660, 'I''ll be ready in 30 minutes.', '我三十分钟内就能准备好。', 'B1', array['i''ll', 'ready', 'minutes']::text[]),
  ('00000000-0000-4000-8000-000000200397', '00000000-0000-4000-8000-000000100004', 81, 286800, 287600, '30 minutes?', '三十分钟？', 'B1', array['minutes']::text[]),
  ('00000000-0000-4000-8000-000000200398', '00000000-0000-4000-8000-000000100004', 82, 288120, 288880, 'Maybe an hour?', '也许一个小时？', 'B1', array['maybe', 'hour']::text[]),
  ('00000000-0000-4000-8000-000000200399', '00000000-0000-4000-8000-000000100004', 83, 289160, 289740, 'That''s ambitious.', '那目标可够高的。', 'B1', array['that''s', 'ambitious']::text[]),
  ('00000000-0000-4000-8000-000000200400', '00000000-0000-4000-8000-000000100004', 84, 290300, 291300, 'All right, he gets a half hour.', '好吧，给他半小时。', 'B1', array['right', 'gets', 'half', 'hour']::text[]),
  ('00000000-0000-4000-8000-000000200401', '00000000-0000-4000-8000-000000100004', 85, 291340, 292980, 'If he''s any longer than that, we''re leaving without him.', '要是他超过那个时间，我们就不等他先走。', 'B1', array['he''s', 'longer', 'than', 'we''re', 'leaving', 'without']::text[]),
  ('00000000-0000-4000-8000-000000200402', '00000000-0000-4000-8000-000000100004', 86, 293080, 293380, 'Thanks, Doug.', '谢了，道格。', 'B1', array['thanks', 'doug']::text[]),
  ('00000000-0000-4000-8000-000000200403', '00000000-0000-4000-8000-000000100004', 87, 293500, 293880, 'Yes, sir.', '遵命，长官。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200404', '00000000-0000-4000-8000-000000100004', 88, 297900, 298620, 'Is your dad?', '是你爸吗？', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200405', '00000000-0000-4000-8000-000000100004', 89, 300680, 301040, 'Yeah.', '嗯。', 'B1', array['yeah']::text[]),
  ('00000000-0000-4000-8000-000000200406', '00000000-0000-4000-8000-000000100004', 90, 304120, 307040, 'Yeah, he''s got a new girlfriend and wants me to meet her.', '是啊，他交了个新女友，想让我去见见她。', 'B1', array['yeah', 'he''s', 'girlfriend', 'wants', 'meet']::text[]),
  ('00000000-0000-4000-8000-000000200407', '00000000-0000-4000-8000-000000100004', 91, 307040, 310040, 'Ah, that''s inevitable, right?', '啊，这是迟早的事，对吧？', 'B1', array['that''s', 'inevitable', 'right']::text[]),
  ('00000000-0000-4000-8000-000000200408', '00000000-0000-4000-8000-000000100004', 92, 315480, 318180, 'Look, I know he can be a dick.', '听着，我知道他有时候是个混蛋。', 'B1', array['look', 'know', 'dick']::text[]),
  ('00000000-0000-4000-8000-000000200409', '00000000-0000-4000-8000-000000100004', 93, 318180, 319200, 'No, he''s more than a dick.', '不，他可不止是个混蛋。', 'B1', array['he''s', 'more', 'than', 'dick']::text[]),
  ('00000000-0000-4000-8000-000000200410', '00000000-0000-4000-8000-000000100004', 94, 319200, 321960, 'Okay, but he''s still your dad.', '好吧，但他终归还是你爸。', 'B1', array['okay', 'he''s', 'still']::text[]),
  ('00000000-0000-4000-8000-000000200411', '00000000-0000-4000-8000-000000100004', 95, 326360, 327540, 'All he cares about is hockey.', '他在乎的只有冰球。', 'B1', array['cares', 'about', 'hockey']::text[]),
  ('00000000-0000-4000-8000-000000200412', '00000000-0000-4000-8000-000000100005', 1, 0, 2740, 'I only matter because I am him.', '我之所以重要，只因为我是他的儿子。', 'B1', array['only', 'matter', 'because']::text[]),
  ('00000000-0000-4000-8000-000000200413', '00000000-0000-4000-8000-000000100005', 2, 3020, 4960, 'I''m just a mini fucking Phil Graham.', '我只是个迷你版的菲尔·格雷厄姆罢了。', 'B1', array['just', 'mini', 'fucking', 'phil', 'graham']::text[]),
  ('00000000-0000-4000-8000-000000200414', '00000000-0000-4000-8000-000000100005', 3, 5240, 7840, 'Yeah, man, I mean, all you''d have to do is win a Stanley Cup,', '是啊，哥们，我是说，你要做的不过就是赢一座斯坦利杯、', 'B1', array['yeah', 'mean', 'you''d', 'have', 'stanley']::text[]),
  ('00000000-0000-4000-8000-000000200415', '00000000-0000-4000-8000-000000100005', 4, 8180, 9740, 'a Norris trophy or two,', '拿一两个诺里斯奖杯、', 'B1', array['norris', 'trophy']::text[]),
  ('00000000-0000-4000-8000-000000200416', '00000000-0000-4000-8000-000000100005', 5, 9900, 11500, 'spend more time on your hair than a Kardashian,', '花在头发上的时间比卡戴珊还多，', 'B1', array['spend', 'more', 'time', 'hair', 'than', 'kardashian']::text[]),
  ('00000000-0000-4000-8000-000000200417', '00000000-0000-4000-8000-000000100005', 6, 11620, 14040, 'and bam, yeah, you''re just like him.', '然后砰，对，你就跟他一模一样了。', 'B1', array['yeah', 'you''re', 'just', 'like']::text[]),
  ('00000000-0000-4000-8000-000000200418', '00000000-0000-4000-8000-000000100005', 7, 15500, 15900, 'Hey.', '嘿。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200419', '00000000-0000-4000-8000-000000100005', 8, 18300, 19300, 'Your dad was great.', '你爸很了不起。', 'B1', array['great']::text[]),
  ('00000000-0000-4000-8000-000000200420', '00000000-0000-4000-8000-000000100005', 9, 19740, 20640, 'Everybody knows it.', '人人都知道。', 'B1', array['everybody', 'knows']::text[]),
  ('00000000-0000-4000-8000-000000200421', '00000000-0000-4000-8000-000000100005', 10, 22020, 24300, 'But no one is expecting you to be him.', '但没人指望你成为他。', 'B1', array['expecting']::text[]),
  ('00000000-0000-4000-8000-000000200422', '00000000-0000-4000-8000-000000100005', 11, 27140, 27780, 'He is.', '他指望。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200423', '00000000-0000-4000-8000-000000100005', 12, 28540, 30380, 'All our parents have expectations, G.', '我们的父母都有各自的期望，G。', 'B1', array['parents', 'have', 'expectations']::text[]),
  ('00000000-0000-4000-8000-000000200424', '00000000-0000-4000-8000-000000100005', 13, 31580, 33940, 'Shit, I''d kill for my dad to even be into hockey,', '妈的，我做梦都想我爸哪怕只是喜欢冰球，', 'B1', array['shit', 'kill', 'even', 'into', 'hockey']::text[]),
  ('00000000-0000-4000-8000-000000200425', '00000000-0000-4000-8000-000000100005', 14, 34060, 34920, 'let alone a damn legend.', '更别说当个传奇了。', 'B1', array['alone', 'damn', 'legend']::text[]),
  ('00000000-0000-4000-8000-000000200426', '00000000-0000-4000-8000-000000100005', 15, 35740, 36300, 'All right?', '好吗？', 'B1', array['right']::text[]),
  ('00000000-0000-4000-8000-000000200427', '00000000-0000-4000-8000-000000100005', 16, 37020, 38380, 'But we''re not doing this for them.', '但我们打球不是为了他们。', 'B1', array['we''re', 'doing', 'them']::text[]),
  ('00000000-0000-4000-8000-000000200428', '00000000-0000-4000-8000-000000100005', 17, 41120, 42400, 'We''re doing this because we love it.', '我们打球是因为我们热爱它。', 'B1', array['we''re', 'doing', 'because', 'love']::text[]),
  ('00000000-0000-4000-8000-000000200429', '00000000-0000-4000-8000-000000100005', 18, 43700, 44060, 'Right?', '对吧？', 'B1', array['right']::text[]),
  ('00000000-0000-4000-8000-000000200430', '00000000-0000-4000-8000-000000100005', 19, 51480, 51840, 'Yeah.', '对。', 'B1', array['yeah']::text[]),
  ('00000000-0000-4000-8000-000000200431', '00000000-0000-4000-8000-000000100005', 20, 54020, 54480, 'Thanks, man.', '谢了，哥们。', 'B1', array['thanks']::text[]),
  ('00000000-0000-4000-8000-000000200432', '00000000-0000-4000-8000-000000100005', 21, 54820, 56300, 'Take a shower. You smell like shit.', '去洗个澡吧。你臭死了。', 'B1', array['take', 'shower', 'smell', 'like', 'shit']::text[]),
  ('00000000-0000-4000-8000-000000200433', '00000000-0000-4000-8000-000000100005', 22, 82420, 83100, 'Hi.', '嗨。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200434', '00000000-0000-4000-8000-000000100005', 23, 84140, 85080, 'You''re in here.', '你在这儿啊。', 'B1', array['you''re', 'here']::text[]),
  ('00000000-0000-4000-8000-000000200435', '00000000-0000-4000-8000-000000100005', 24, 85880, 88540, 'I can''t pull an all-nighter in my room. I''ll fall asleep.', '我在自己房间没法通宵。我会睡着的。', 'B1', array['can''t', 'pull', 'nighter', 'room', 'i''ll', 'fall']::text[]),
  ('00000000-0000-4000-8000-000000200436', '00000000-0000-4000-8000-000000100005', 25, 88820, 90720, 'Fair enough. How''s it coming?', '有道理。进展怎么样？', 'B1', array['fair', 'enough', 'how''s', 'coming']::text[]),
  ('00000000-0000-4000-8000-000000200437', '00000000-0000-4000-8000-000000100005', 26, 91660, 93000, 'I have a melody.', '我有了段旋律。', 'B1', array['have', 'melody']::text[]),
  ('00000000-0000-4000-8000-000000200438', '00000000-0000-4000-8000-000000100005', 27, 93440, 94580, 'No lyrics, though.', '不过还没歌词。', 'B1', array['lyrics', 'though']::text[]),
  ('00000000-0000-4000-8000-000000200439', '00000000-0000-4000-8000-000000100005', 28, 94800, 97160, 'Well, that''s great. That''s like halfway done, right?', '那也很棒啊。那不就等于完成一半了吗？', 'B1', array['well', 'that''s', 'great', 'like', 'halfway', 'done']::text[]),
  ('00000000-0000-4000-8000-000000200440', '00000000-0000-4000-8000-000000100005', 29, 97360, 100540, 'No, not really. Lyrics are kind of a big thing in pop.', '不，并不是。歌词在流行乐里可是个大头。', 'B1', array['really', 'lyrics', 'kind', 'thing']::text[]),
  ('00000000-0000-4000-8000-000000200441', '00000000-0000-4000-8000-000000100005', 30, 101000, 102360, 'That''s why classical is easier.', '所以古典乐才更容易。', 'B1', array['that''s', 'classical', 'easier']::text[]),
  ('00000000-0000-4000-8000-000000200442', '00000000-0000-4000-8000-000000100005', 31, 102740, 105520, 'Dude, I have seen your sheet music. Classical is not easier.', '哥们，我可见过你的乐谱。古典乐才不更容易。', 'B1', array['dude', 'have', 'seen', 'sheet', 'music', 'classical']::text[]),
  ('00000000-0000-4000-8000-000000200443', '00000000-0000-4000-8000-000000100005', 32, 107580, 108360, 'Definitely is.', '绝对更容易。', 'B1', array['definitely']::text[]),
  ('00000000-0000-4000-8000-000000200444', '00000000-0000-4000-8000-000000100005', 33, 109980, 112080, 'Well, have you ever written a pop song before?', '那，你以前写过流行歌吗？', 'B1', array['well', 'have', 'ever', 'written', 'song', 'before']::text[]),
  ('00000000-0000-4000-8000-000000200445', '00000000-0000-4000-8000-000000100005', 34, 112900, 114020, 'Uh, not since high school.', '呃，高中以后就没写过了。', 'B1', array['since', 'high', 'school']::text[]),
  ('00000000-0000-4000-8000-000000200446', '00000000-0000-4000-8000-000000100005', 35, 115080, 115840, 'I''ll come back to you.', '我待会儿再来找你。', 'B1', array['i''ll', 'come', 'back']::text[]),
  ('00000000-0000-4000-8000-000000200447', '00000000-0000-4000-8000-000000100005', 36, 116300, 117080, 'Riding a bike.', '就像骑自行车（熟能生巧）。', 'B1', array['riding', 'bike']::text[]),
  ('00000000-0000-4000-8000-000000200448', '00000000-0000-4000-8000-000000100005', 37, 118960, 119600, 'Yeah, maybe.', '嗯，也许吧。', 'B1', array['yeah', 'maybe']::text[]),
  ('00000000-0000-4000-8000-000000200449', '00000000-0000-4000-8000-000000100005', 38, 120820, 121260, 'Hey.', '嘿。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200450', '00000000-0000-4000-8000-000000100005', 39, 122660, 123860, 'You''re nice to my friend, Hannah.', '你对我朋友汉娜真好。', 'B1', array['you''re', 'nice', 'friend', 'hannah']::text[]),
  ('00000000-0000-4000-8000-000000200451', '00000000-0000-4000-8000-000000100005', 40, 124800, 126180, 'You just started writing.', '你才刚开始写。', 'B1', array['just', 'started', 'writing']::text[]),
  ('00000000-0000-4000-8000-000000200452', '00000000-0000-4000-8000-000000100005', 41, 126420, 127680, 'These things take time, right?', '这种事是需要时间的，对吧？', 'B1', array['these', 'things', 'take', 'time', 'right']::text[]),
  ('00000000-0000-4000-8000-000000200453', '00000000-0000-4000-8000-000000100005', 42, 130380, 131800, 'What if I can''t?', '要是我写不出来怎么办？', 'B1', array['what', 'can''t']::text[]),
  ('00000000-0000-4000-8000-000000200454', '00000000-0000-4000-8000-000000100005', 43, 131820, 132220, 'I''ll...', '我会……', 'B1', array['i''ll']::text[]),
  ('00000000-0000-4000-8000-000000200455', '00000000-0000-4000-8000-000000100005', 44, 133080, 135300, 'What if I write a terrible song', '要是我写出一首烂歌，', 'B1', array['what', 'write', 'terrible', 'song']::text[]),
  ('00000000-0000-4000-8000-000000200456', '00000000-0000-4000-8000-000000100005', 45, 135300, 136920, 'and I fail the pop showcase', '搞砸了流行乐汇演，', 'B1', array['fail', 'showcase']::text[]),
  ('00000000-0000-4000-8000-000000200457', '00000000-0000-4000-8000-000000100005', 46, 136920, 140100, 'and I can''t afford my tuition next semester?', '然后下学期连学费都付不起怎么办？', 'B1', array['can''t', 'afford', 'tuition', 'next', 'semester']::text[]),
  ('00000000-0000-4000-8000-000000200458', '00000000-0000-4000-8000-000000100005', 47, 140440, 141880, 'You know, like, what if you''re right?', '你知道吗，万一你说对了呢？', 'B1', array['know', 'like', 'what', 'you''re', 'right']::text[]),
  ('00000000-0000-4000-8000-000000200459', '00000000-0000-4000-8000-000000100005', 48, 142000, 143400, 'If I don''t fall in love,', '万一我没能坠入爱河，', 'B1', array['don''t', 'fall', 'love']::text[]),
  ('00000000-0000-4000-8000-000000200460', '00000000-0000-4000-8000-000000100005', 49, 145080, 148920, 'and write a perfect song about love and life and heartbreak.', '写不出一首关于爱、生活和心碎的完美歌曲呢？', 'B1', array['write', 'perfect', 'song', 'about', 'love', 'life']::text[]),
  ('00000000-0000-4000-8000-000000200461', '00000000-0000-4000-8000-000000100005', 50, 149080, 151640, 'Hey, hey, you are setting the bar way too high.', '嘿，嘿，你把标准定得太高了。', 'B1', array['setting', 'high']::text[]),
  ('00000000-0000-4000-8000-000000200462', '00000000-0000-4000-8000-000000100005', 51, 151960, 154960, 'I mean, of course you''re going to fall in love someday.', '我是说，你总有一天当然会坠入爱河的。', 'B1', array['mean', 'course', 'you''re', 'going', 'fall', 'love']::text[]),
  ('00000000-0000-4000-8000-000000200463', '00000000-0000-4000-8000-000000100005', 52, 156140, 157460, 'Maybe it''ll be with Justin.', '也许会是跟贾斯汀。', 'B1', array['maybe', 'it''ll', 'justin']::text[]),
  ('00000000-0000-4000-8000-000000200464', '00000000-0000-4000-8000-000000100005', 53, 157560, 158700, 'Maybe someone else.', '也许是别的什么人。', 'B1', array['maybe', 'someone', 'else']::text[]),
  ('00000000-0000-4000-8000-000000200465', '00000000-0000-4000-8000-000000100005', 54, 160380, 163720, 'No, I''ve just been staring at this blank page all night,', '不行，我整晚就盯着这张白纸，', 'B1', array['i''ve', 'just', 'been', 'staring', 'blank', 'page']::text[]),
  ('00000000-0000-4000-8000-000000200466', '00000000-0000-4000-8000-000000100005', 55, 163820, 166280, 'and I have literally no idea what it should be about.', '完全不知道该写些什么。', 'B1', array['have', 'literally', 'idea', 'what', 'should', 'about']::text[]),
  ('00000000-0000-4000-8000-000000200467', '00000000-0000-4000-8000-000000100005', 56, 167460, 168780, 'What did you write about in high school?', '你高中时都写些什么？', 'B1', array['what', 'write', 'about', 'high', 'school']::text[]),
