  ('00000000-0000-4000-8000-000000200483', '00000000-0000-4000-8000-000000100005', 72, 250620, 252560, 'Ain''t as young as I fucking used to be.', '我可他妈没以前那么年轻了。', 'B1', array['ain''t', 'young', 'fucking', 'used']::text[]),
