  ('00000000-0000-4000-8000-000000200492', '00000000-0000-4000-8000-000000100005', 81, 261920, 263120, 'You''re not having to make so much money.', '你不用赚那么多钱啦。', 'B1', array['you''re', 'having', 'make', 'much', 'money']::text[]),
