  ('00000000-0000-4000-8000-000000200496', '00000000-0000-4000-8000-000000100005', 85, 273480, 273900, 'Hi.', '嗨。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200497', '00000000-0000-4000-8000-000000100005', 86, 274140, 276460, 'Picking up a takeaway order for Justin Koch?', '来取贾斯汀·科尔的外卖订单？', 'B1', array['picking', 'takeaway', 'order', 'justin', 'koch']::text[]),
