  ('00000000-0000-4000-8000-000000200500', '00000000-0000-4000-8000-000000100005', 89, 281040, 283060, 'We''ve spoken, kind of.', '我们……算是说过话。', 'B1', array['we''ve', 'spoken', 'kind']::text[]),
