  ('00000000-0000-4000-8000-000000200502', '00000000-0000-4000-8000-000000100005', 91, 286860, 287880, 'Yeah, thanks.', '是吗，谢谢。', 'B1', array['yeah', 'thanks']::text[]),
  ('00000000-0000-4000-8000-000000200503', '00000000-0000-4000-8000-000000100005', 92, 288880, 290880, 'I''m not, like, a creepy soccer fan or anything.', '我不是那种很瘆人的死忠粉什么的。', 'B1', array['like', 'creepy', 'soccer', 'anything']::text[]),
  ('00000000-0000-4000-8000-000000200504', '00000000-0000-4000-8000-000000100005', 93, 291000, 293300, 'I work here, so I''ve heard you.', '我在这儿打工，所以听过你们的演出。', 'B1', array['work', 'here', 'i''ve', 'heard']::text[]),
