  ('00000000-0000-4000-8000-000000200507', '00000000-0000-4000-8000-000000100005', 96, 299420, 300980, 'I carried a watermelon.', '我搬了个大西瓜。', 'B1', array['carried', 'watermelon']::text[]),
  ('00000000-0000-4000-8000-000000200508', '00000000-0000-4000-8000-000000100005', 97, 302580, 303120, 'What?', '什么？', 'B1', array['what']::text[]),
  ('00000000-0000-4000-8000-000000200509', '00000000-0000-4000-8000-000000100005', 98, 304480, 305320, 'Dirty dancing.', '《辣身舞》。', 'B1', array['dirty', 'dancing']::text[]),
  ('00000000-0000-4000-8000-000000200510', '00000000-0000-4000-8000-000000100005', 99, 305620, 310280, 'Um, Jennifer Grey''s this really awkward moment with Patrick Swayze when I...', '呃，就是詹妮弗·格雷跟帕特里克·斯威兹之间那个特别尴尬的瞬间，当我……', 'B1', array['jennifer', 'grey''s', 'really', 'awkward', 'moment', 'patrick']::text[]),
  ('00000000-0000-4000-8000-000000200511', '00000000-0000-4000-8000-000000100005', 100, 311000, 313600, 'Sorry, never mind. Yeah, obviously I work here.', '抱歉，当我没说。对，显然我是在这儿打工的。', 'B1', array['sorry', 'never', 'mind', 'yeah', 'obviously', 'work']::text[]),
  ('00000000-0000-4000-8000-000000200512', '00000000-0000-4000-8000-000000100005', 101, 314900, 316700, 'Look, I''m kind of in a rush. Can I...', '听着，我有点赶时间。我能不能……', 'B1', array['look', 'kind', 'rush']::text[]),
  ('00000000-0000-4000-8000-000000200513', '00000000-0000-4000-8000-000000100005', 102, 316700, 317360, 'Oh my god, yeah.', '哦天哪，当然。', 'B1', array['yeah']::text[]),
  ('00000000-0000-4000-8000-000000200514', '00000000-0000-4000-8000-000000100005', 103, 317400, 318160, 'Yeah, sorry.', '对，抱歉。', 'B1', array['yeah', 'sorry']::text[]),
  ('00000000-0000-4000-8000-000000200515', '00000000-0000-4000-8000-000000100005', 104, 318540, 319280, 'Thank you.', '谢谢。', 'B1', array['thank']::text[]),
  ('00000000-0000-4000-8000-000000200516', '00000000-0000-4000-8000-000000100005', 105, 319400, 319920, 'Yeah.', '嗯。', 'B1', array['yeah']::text[]),
  ('00000000-0000-4000-8000-000000200517', '00000000-0000-4000-8000-000000100005', 106, 320980, 321520, 'Bye.', '再见。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200518', '00000000-0000-4000-8000-000000100005', 107, 322800, 323340, 'Smooth.', '真会撩。', 'B1', array['smooth']::text[]),
  ('00000000-0000-4000-8000-000000200519', '00000000-0000-4000-8000-000000100005', 108, 325080, 328660, '"I carried a watermelon." Anyone ever tell you that eavesdropping is rude?', '"我搬了个大西瓜"。有没有人跟你说过偷听别人讲话很没礼貌？', 'B1', array['carried', 'watermelon', 'anyone', 'ever', 'tell', 'eavesdropping']::text[]),
  ('00000000-0000-4000-8000-000000200520', '00000000-0000-4000-8000-000000100006', 1, 0, 1620, 'Did anyone ever tell you that your references are dated?', '有没有人跟你说过你举的例子都过时了？', 'B1', array['anyone', 'ever', 'tell', 'references', 'dated']::text[]),
  ('00000000-0000-4000-8000-000000200521', '00000000-0000-4000-8000-000000100006', 2, 2060, 2820, 'It''s a classic.', '那是经典。', 'B1', array['it''s', 'classic']::text[]),
  ('00000000-0000-4000-8000-000000200522', '00000000-0000-4000-8000-000000100006', 3, 3620, 5760, 'I just came over here to see if we could place an order.', '我过来只是想看看能不能点单。', 'B1', array['just', 'came', 'over', 'here', 'could', 'place']::text[]),
  ('00000000-0000-4000-8000-000000200523', '00000000-0000-4000-8000-000000100006', 4, 6160, 8100, 'Or is it like a self-serve kind of day?', '还是说今天是自助的日子？', 'B1', array['like', 'self', 'serve', 'kind']::text[]),
