  ('00000000-0000-4000-8000-000000200525', '00000000-0000-4000-8000-000000100006', 6, 11620, 12920, 'You know, you shouldn''t fawn over him.', '跟你说，你不该对他这么献殷勤。', 'B1', array['know', 'shouldn''t', 'fawn', 'over']::text[]),
  ('00000000-0000-4000-8000-000000200526', '00000000-0000-4000-8000-000000100006', 7, 13060, 13420, 'What?', '什么？', 'B1', array['what']::text[]),
  ('00000000-0000-4000-8000-000000200527', '00000000-0000-4000-8000-000000100006', 8, 13540, 14620, 'That guy. You''re too available.', '那个家伙。你太容易到手了。', 'B1', array['you''re', 'available']::text[]),
  ('00000000-0000-4000-8000-000000200528', '00000000-0000-4000-8000-000000100006', 9, 15100, 17440, 'Like the girls throwing themselves at you over there?', '就像那边那些往你身上扑的姑娘一样？', 'B1', array['like', 'girls', 'throwing', 'themselves', 'over', 'there']::text[]),
  ('00000000-0000-4000-8000-000000200529', '00000000-0000-4000-8000-000000100006', 10, 17600, 18440, 'That''s a different scenario.', '那是另一码事。', 'B1', array['that''s', 'different', 'scenario']::text[]),
  ('00000000-0000-4000-8000-000000200530', '00000000-0000-4000-8000-000000100006', 11, 18780, 20180, 'I don''t do girlfriends. They know that.', '我不谈女朋友。她们都知道。', 'B1', array['don''t', 'girlfriends', 'they', 'know']::text[]),
  ('00000000-0000-4000-8000-000000200531', '00000000-0000-4000-8000-000000100006', 12, 20460, 22260, 'Okay, well, congratulations, Casanova.', '好吧，那恭喜你了，卡萨诺瓦（情圣）。', 'B1', array['okay', 'well', 'congratulations', 'casanova']::text[]),
  ('00000000-0000-4000-8000-000000200532', '00000000-0000-4000-8000-000000100006', 13, 22440, 23300, 'But I don''t need your help.', '但我不需要你的帮助。', 'B1', array['don''t', 'need', 'help']::text[]),
  ('00000000-0000-4000-8000-000000200533', '00000000-0000-4000-8000-000000100006', 14, 24160, 24520, 'Refill?', '续杯吗？', 'B1', array['refill']::text[]),
  ('00000000-0000-4000-8000-000000200534', '00000000-0000-4000-8000-000000100006', 15, 24620, 25040, 'Yeah, please.', '好，麻烦了。', 'B1', array['yeah', 'please']::text[]),
