  ('00000000-0000-4000-8000-000000200536', '00000000-0000-4000-8000-000000100006', 17, 27960, 28960, 'What if I paid you?', '要是我付钱呢？', 'B1', array['what', 'paid']::text[]),
  ('00000000-0000-4000-8000-000000200537', '00000000-0000-4000-8000-000000100006', 18, 30000, 30860, 'to take your dating advice.', '付钱听你的恋爱建议。', 'B1', array['take', 'dating', 'advice']::text[]),
  ('00000000-0000-4000-8000-000000200538', '00000000-0000-4000-8000-000000100006', 19, 31200, 32220, 'To tutor me, nerd.', '是付钱让你当我的家教，书呆子。', 'B1', array['tutor', 'nerd']::text[]),
  ('00000000-0000-4000-8000-000000200539', '00000000-0000-4000-8000-000000100006', 20, 33460, 34780, 'You could just ask my name.', '你直接问我名字不就行了。', 'B1', array['could', 'just', 'name']::text[]),
  ('00000000-0000-4000-8000-000000200540', '00000000-0000-4000-8000-000000100006', 21, 35100, 37080, 'Usually, girls just tell me.', '通常，姑娘们都是主动告诉我她们的名字。', 'B1', array['usually', 'girls', 'just', 'tell']::text[]),
  ('00000000-0000-4000-8000-000000200541', '00000000-0000-4000-8000-000000100006', 22, 38040, 39420, 'Come on, I''ll pay you anything.', '拜托，我什么都肯付。', 'B1', array['come', 'i''ll', 'anything']::text[]),
  ('00000000-0000-4000-8000-000000200542', '00000000-0000-4000-8000-000000100006', 23, 39500, 41180, 'You''re the only one who got an A on that paper.', '那篇论文只有你一个人拿了 A。', 'B1', array['you''re', 'only', 'paper']::text[]),
  ('00000000-0000-4000-8000-000000200543', '00000000-0000-4000-8000-000000100006', 24, 41440, 41700, 'So?', '所以呢？', 'B1', array[]::text[]),
