  ('00000000-0000-4000-8000-000000200545', '00000000-0000-4000-8000-000000100006', 26, 44660, 46700, 'Why? Because you get off on beating people up?', '为什么？因为揍人能让你爽吗？', 'B1', array['because', 'beating', 'people']::text[]),
  ('00000000-0000-4000-8000-000000200546', '00000000-0000-4000-8000-000000100006', 27, 47140, 47540, 'What?', '什么？', 'B1', array['what']::text[]),
