  ('00000000-0000-4000-8000-000000200548', '00000000-0000-4000-8000-000000100006', 29, 50680, 52300, 'that doesn''t eject its players for fighting.', '打架却不会把球员罚下场。', 'B1', array['doesn''t', 'eject', 'players', 'fighting']::text[]),
