  ('00000000-0000-4000-8000-000000200581', '00000000-0000-4000-8000-000000100006', 62, 136120, 139200, 'Did you drive all the way out here to congratulate me or make me feel like I fucked up somehow?', '你大老远开车过来，是为了恭喜我，还是为了让我觉得自己又搞砸了什么？', 'B1', array['drive', 'here', 'congratulate', 'make', 'feel', 'like']::text[]),
  ('00000000-0000-4000-8000-000000200582', '00000000-0000-4000-8000-000000100006', 63, 139420, 142060, 'Look, I tried calling you earlier, but you don''t answer...', '听着，我之前给你打过电话，可你不接……', 'B1', array['look', 'tried', 'calling', 'earlier', 'don''t', 'answer']::text[]),
