  ('00000000-0000-4000-8000-000000200588', '00000000-0000-4000-8000-000000100006', 69, 153740, 155000, 'Cindy and I are getting married.', '辛迪和我要结婚了。', 'B1', array['cindy', 'getting', 'married']::text[]),
  ('00000000-0000-4000-8000-000000200589', '00000000-0000-4000-8000-000000100006', 70, 158760, 160500, 'You''ve been dating for, like, two seconds.', '你们才刚谈了没多久吧。', 'B1', array['you''ve', 'been', 'dating', 'like', 'seconds']::text[]),
