  ('00000000-0000-4000-8000-000000200592', '00000000-0000-4000-8000-000000100006', 73, 163420, 164440, 'Does she even fucking know you?', '她他妈真了解你吗？', 'B1', array['does', 'even', 'fucking', 'know']::text[]),
