  ('00000000-0000-4000-8000-000000200599', '00000000-0000-4000-8000-000000100006', 80, 171040, 172040, 'She wants to meet you.', '她想见见你。', 'B1', array['wants', 'meet']::text[]),
  ('00000000-0000-4000-8000-000000200600', '00000000-0000-4000-8000-000000100006', 81, 172140, 173180, 'Your timing is fucking shit.', '你挑的这时机烂透了。', 'B1', array['timing', 'fucking', 'shit']::text[]),
