  ('00000000-0000-4000-8000-000000200608', '00000000-0000-4000-8000-000000100006', 89, 186500, 188120, 'I''m in the lead and I''m breaking the wave.', '我一马当先，乘风破浪。', 'B1', array['lead', 'breaking', 'wave']::text[]),
