  ('00000000-0000-4000-8000-000000200611', '00000000-0000-4000-8000-000000100006', 92, 196640, 197080, 'Schumacher!', '舒马赫！', 'B1', array['schumacher']::text[]),
  ('00000000-0000-4000-8000-000000200612', '00000000-0000-4000-8000-000000100006', 93, 219320, 223560, 'I think he has the potential, honestly, to have a bigger impact than Phil ever had.', '说实话，我觉得他有潜力造成比菲尔当年更大的影响力。', 'B1', array['think', 'potential', 'honestly', 'have', 'bigger', 'impact']::text[]),
  ('00000000-0000-4000-8000-000000200613', '00000000-0000-4000-8000-000000100006', 94, 223760, 226040, 'All right, I can''t wait to hear what Phil has to say about that.', '好的，我都等不及想听听菲尔对此怎么说了。', 'B1', array['right', 'can''t', 'wait', 'hear', 'what', 'phil']::text[]),
