  ('00000000-0000-4000-8000-000000200615', '00000000-0000-4000-8000-000000100006', 96, 243920, 245700, 'Garrett Graham is a bigger player.', '加勒特·格雷厄姆是个更高大的球员。', 'B1', array['garrett', 'graham', 'bigger', 'player']::text[]),
