  ('00000000-0000-4000-8000-000000200618', '00000000-0000-4000-8000-000000100006', 99, 251020, 251760, 'What are you doing, G?', '你在干什么，G？', 'B1', array['what', 'doing']::text[]),
  ('00000000-0000-4000-8000-000000200619', '00000000-0000-4000-8000-000000100006', 100, 255380, 257240, 'Come on, bro. Get your head in it.', '振作点，兄弟。把心思放到比赛上。', 'B1', array['come', 'head']::text[]),
  ('00000000-0000-4000-8000-000000200620', '00000000-0000-4000-8000-000000100006', 101, 262240, 264960, 'His dad has certainly taught him everything he knows, right?', '他爸肯定把自己的本事都倾囊相授了，对吧？', 'B1', array['certainly', 'taught', 'everything', 'knows', 'right']::text[]),
