  ('00000000-0000-4000-8000-000000200623', '00000000-0000-4000-8000-000000100006', 104, 268780, 270080, 'Making daddy proud, Graham?', '在让你老爸长脸呢，格雷厄姆？', 'B1', array['making', 'daddy', 'proud', 'graham']::text[]),
