  ('00000000-0000-4000-8000-000000200630', '00000000-0000-4000-8000-000000100006', 111, 295300, 296880, 'Derek Graham turns out to be.', '最终会成为怎样的球员。', 'B1', array['derek', 'graham', 'turns']::text[]),
  ('00000000-0000-4000-8000-000000200631', '00000000-0000-4000-8000-000000100006', 112, 298660, 300420, 'Yeah, fuck you, Spade. Beat you.', '是啊，去你的，斯佩德。揍了你。', 'B1', array['yeah', 'fuck', 'spade', 'beat']::text[]),
  ('00000000-0000-4000-8000-000000200632', '00000000-0000-4000-8000-000000100006', 113, 304480, 307840, 'He said that? You know, Garrett doesn''t do the girlfriend thing.', '他这么说的？要知道，加勒特从不谈女朋友。', 'B1', array['said', 'know', 'garrett', 'doesn''t', 'girlfriend', 'thing']::text[]),
  ('00000000-0000-4000-8000-000000200633', '00000000-0000-4000-8000-000000100006', 114, 307940, 309620, 'He also doesn''t do the repeat hookups thing.', '他也从不跟同一个人反复约炮。', 'B1', array['also', 'doesn''t', 'repeat', 'hookups', 'thing']::text[]),
  ('00000000-0000-4000-8000-000000200634', '00000000-0000-4000-8000-000000100006', 115, 309660, 311800, 'Even hooking up since summer. Whatever. Good friends.', '从夏天起就一直在约……随便吧。好朋友而已。', 'B1', array['even', 'hooking', 'since', 'summer', 'whatever', 'good']::text[]),
  ('00000000-0000-4000-8000-000000200635', '00000000-0000-4000-8000-000000100006', 116, 312040, 314220, 'And honestly, he''s playing like shit.', '而且说实话，他今天打得烂透了。', 'B1', array['honestly', 'he''s', 'playing', 'like', 'shit']::text[]),
