  ('00000000-0000-4000-8000-000000200637', '00000000-0000-4000-8000-000000100006', 118, 316200, 317640, 'I told you they''re fucking losers.', '我就说他们是一群废物。', 'B1', array['told', 'they''re', 'fucking', 'losers']::text[]),
  ('00000000-0000-4000-8000-000000200638', '00000000-0000-4000-8000-000000100006', 119, 318800, 320980, 'Let''s hope they keep at it. We''ll destroy them.', '但愿他们继续这么烂。我们会把他们打得落花流水。', 'B1', array['let''s', 'hope', 'they', 'keep', 'we''ll', 'destroy']::text[]),
  ('00000000-0000-4000-8000-000000200639', '00000000-0000-4000-8000-000000100006', 120, 321500, 323640, 'Hell yeah. Let me get some of that, Delaney.', '那必须的。给我也来点，德莱尼。', 'B1', array['hell', 'yeah', 'some', 'delaney']::text[]),
  ('00000000-0000-4000-8000-000000200640', '00000000-0000-4000-8000-000000100006', 121, 324000, 324820, 'Got you, bro.', '给你，兄弟。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200641', '00000000-0000-4000-8000-000000100007', 1, 6300, 9300, 'I love you.', '我爱你。', 'B1', array['love']::text[]),
  ('00000000-0000-4000-8000-000000200642', '00000000-0000-4000-8000-000000100007', 2, 51200, 52540, 'Hey, Garrett!', '嘿，加勒特！', 'B1', array['garrett']::text[]),
  ('00000000-0000-4000-8000-000000200643', '00000000-0000-4000-8000-000000100007', 3, 54400, 55780, 'Hey, the game''s not over!', '嘿，比赛还没结束呢！', 'B1', array['game''s', 'over']::text[]),
  ('00000000-0000-4000-8000-000000200644', '00000000-0000-4000-8000-000000100007', 4, 106320, 109940, 'I was just a fire when I was five', '我五岁时就是团火', 'B1', array['just', 'fire', 'when', 'five']::text[]),
