  ('00000000-0000-4000-8000-000000200646', '00000000-0000-4000-8000-000000100007', 6, 113580, 117400, 'Times are changing now, the war getting fast', '如今时代在变，战火越烧越急', 'B1', array['times', 'changing', 'getting', 'fast']::text[]),
