  ('00000000-0000-4000-8000-000000200800', '00000000-0000-4000-8000-000000100008', 88, 283440, 286040, 'Why do you look good in a coat?', '你穿外套怎么这么好看？', 'B1', array['look', 'good', 'coat']::text[]),
