  ('00000000-0000-4000-8000-000000200812', '00000000-0000-4000-8000-000000100009', 2, 1560, 4020, 'But I''m trying out other styles, too.', '不过我也在尝试别的风格。', 'B1', array['trying', 'other', 'styles']::text[]),
