  ('00000000-0000-4000-8000-000000200814', '00000000-0000-4000-8000-000000100009', 4, 10680, 13440, 'But mostly pop, though, and classical.', '不过主要还是流行乐和古典乐。', 'B1', array['mostly', 'though', 'classical']::text[]),
