  ('00000000-0000-4000-8000-000000200816', '00000000-0000-4000-8000-000000100009', 6, 16580, 18500, 'Babe, I am always telling you to wear your jacket.', '宝贝，我总叫你穿上外套。', 'B1', array['babe', 'always', 'telling', 'wear', 'jacket']::text[]),
