  ('00000000-0000-4000-8000-000000200821', '00000000-0000-4000-8000-000000100009', 11, 27640, 28540, 'I know you well, man.', '我跟你很熟，老兄。', 'B1', array['know', 'well']::text[]),
  ('00000000-0000-4000-8000-000000200822', '00000000-0000-4000-8000-000000100009', 12, 30120, 31920, 'Yeah, thanks, man. No worries.', '嗯，谢了，老兄。没事的。', 'B1', array['yeah', 'thanks', 'worries']::text[]),
  ('00000000-0000-4000-8000-000000200823', '00000000-0000-4000-8000-000000100009', 13, 32620, 33980, 'You''re a hockey fan?', '你是冰球迷？', 'B1', array['you''re', 'hockey']::text[]),
