  ('00000000-0000-4000-8000-000000200840', '00000000-0000-4000-8000-000000100009', 30, 67080, 68420, 'And how do you suddenly know my name?', '还有你怎么突然就知道我名字了？', 'B1', array['suddenly', 'know', 'name']::text[]),
