  ('00000000-0000-4000-8000-000000200849', '00000000-0000-4000-8000-000000100009', 39, 83200, 85740, 'You really have a healthy opinion of yourself, don''t you?', '你对自己的评价还真是相当不错啊，是吧？', 'B1', array['really', 'have', 'healthy', 'opinion', 'yourself', 'don''t']::text[]),
