  ('00000000-0000-4000-8000-000000200870', '00000000-0000-4000-8000-000000100009', 60, 111340, 124540, 'nice to you. You''re a music major, right? I saw your Instagram. You sort of disappear when you play.', '对你好。你是音乐专业的，对吧？我看了你的 Instagram。你弹奏的时候，整个人有点像是消失了。', 'B1', array['nice', 'you''re', 'music', 'major', 'right', 'instagram']::text[]),
  ('00000000-0000-4000-8000-000000200871', '00000000-0000-4000-8000-000000100009', 61, 125240, 132740, 'I don''t mean that in a bad way. I mean, you love it. I can tell.', '我没有恶意。我是说，你热爱它。我看得出来。', 'B1', array['don''t', 'mean', 'love', 'tell']::text[]),
  ('00000000-0000-4000-8000-000000200872', '00000000-0000-4000-8000-000000100009', 62, 134540, 135860, 'Don''t you love hockey like that?', '难道你不也那样热爱冰球吗？', 'B1', array['don''t', 'love', 'hockey', 'like']::text[]),
  ('00000000-0000-4000-8000-000000200873', '00000000-0000-4000-8000-000000100009', 63, 138900, 139820, 'I don''t know.', '我不知道。', 'B1', array['don''t', 'know']::text[]),
  ('00000000-0000-4000-8000-000000200874', '00000000-0000-4000-8000-000000100009', 64, 141540, 147280, 'It''s just something I''ve always done to impress my dad.', '它只是一件我一直在做、为了让我爸刮目相看的事。', 'B1', array['it''s', 'just', 'something', 'i''ve', 'always', 'done']::text[]),
  ('00000000-0000-4000-8000-000000200875', '00000000-0000-4000-8000-000000100009', 65, 149180, 150100, 'And does it?', '那有用吗？', 'B1', array['does']::text[]),
  ('00000000-0000-4000-8000-000000200876', '00000000-0000-4000-8000-000000100009', 66, 151780, 152960, 'Nothing impresses him.', '什么都打动不了他。', 'B1', array['nothing', 'impresses']::text[]),
  ('00000000-0000-4000-8000-000000200877', '00000000-0000-4000-8000-000000100009', 67, 153240, 154720, 'Not really.', '并没有。', 'B1', array['really']::text[]),
  ('00000000-0000-4000-8000-000000200878', '00000000-0000-4000-8000-000000100009', 68, 157040, 158200, 'What about your mom?', '那你妈妈呢？', 'B1', array['what', 'about']::text[]),
  ('00000000-0000-4000-8000-000000200879', '00000000-0000-4000-8000-000000100009', 69, 161320, 162360, 'She, um...', '她，嗯……', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200880', '00000000-0000-4000-8000-000000100009', 70, 165860, 169900, 'She died a while back. Cancer.', '她前些年去世了，癌症。', 'B1', array['died', 'while', 'back', 'cancer']::text[]),
  ('00000000-0000-4000-8000-000000200881', '00000000-0000-4000-8000-000000100009', 71, 172160, 172560, 'Look.', '听着。', 'B1', array['look']::text[]),
  ('00000000-0000-4000-8000-000000200882', '00000000-0000-4000-8000-000000100009', 72, 177380, 185320, 'I don''t believe in favors or shortcuts. I don''t want to pass this class because somebody handed me the grade. I want to earn it, and', '我不信什么人情或走捷径。我不想靠别人施舍的分数通过这门课。我想凭本事挣来，而且', 'B1', array['don''t', 'believe', 'favors', 'shortcuts', 'want', 'pass']::text[]),
  ('00000000-0000-4000-8000-000000200883', '00000000-0000-4000-8000-000000100009', 73, 187420, 189380, 'I''m pretty sure you''re the only one who can help me do that.', '我很确定，你是唯一能帮我做到这点的人。', 'B1', array['pretty', 'sure', 'you''re', 'only', 'help']::text[]),
  ('00000000-0000-4000-8000-000000200884', '00000000-0000-4000-8000-000000100009', 74, 191280, 197420, 'So what? I help you study for the midterm and you play my fake boyfriend to get Justin''s attention?', '所以呢？我帮你复习期中考，你来当我的假男友、好引起贾斯汀的注意？', 'B1', array['what', 'help', 'study', 'midterm', 'play', 'fake']::text[]),
  ('00000000-0000-4000-8000-000000200885', '00000000-0000-4000-8000-000000100009', 75, 199580, 200540, 'Something like that.', '差不多就是那样。', 'B1', array['something', 'like']::text[]),
  ('00000000-0000-4000-8000-000000200886', '00000000-0000-4000-8000-000000100009', 76, 202220, 203620, 'You still have to pay me.', '你还是得付我钱。', 'B1', array['still', 'have']::text[]),
  ('00000000-0000-4000-8000-000000200887', '00000000-0000-4000-8000-000000100009', 77, 205000, 205520, 'Obviously.', '那当然。', 'B1', array['obviously']::text[]),
  ('00000000-0000-4000-8000-000000200888', '00000000-0000-4000-8000-000000100009', 78, 216220, 219560, 'Don''t forget, I''m not your girl, Graham.', '别忘了，我可不是你的女人，格雷厄姆。', 'B1', array['don''t', 'forget', 'girl', 'graham']::text[]),
  ('00000000-0000-4000-8000-000000200889', '00000000-0000-4000-8000-000000100009', 79, 221300, 223920, 'This is my dance space. This is your dance space.', '这是我的舞蹈空间。这是你的舞蹈空间。', 'B1', array['dance', 'space']::text[]),
  ('00000000-0000-4000-8000-000000200890', '00000000-0000-4000-8000-000000100009', 80, 224220, 225940, 'I don''t go into yours, you don''t come into mine.', '我不进你的，你也别进我的。', 'B1', array['don''t', 'into', 'yours', 'come', 'mine']::text[]),
  ('00000000-0000-4000-8000-000000200891', '00000000-0000-4000-8000-000000100009', 81, 226460, 227820, 'You''ve seen Dirty Dancing.', '你看过《辣身舞》。', 'B1', array['you''ve', 'seen', 'dirty', 'dancing']::text[]),
  ('00000000-0000-4000-8000-000000200892', '00000000-0000-4000-8000-000000100009', 82, 228540, 230020, 'That''s my mom''s favorite movie.', '那是我妈最爱的电影。', 'B1', array['that''s', 'mom''s', 'favorite', 'movie']::text[]),
  ('00000000-0000-4000-8000-000000200893', '00000000-0000-4000-8000-000000100009', 83, 232880, 234320, 'Still a dated reference, though.', '不过还是个过时的梗。', 'B1', array['still', 'dated', 'reference', 'though']::text[]),
  ('00000000-0000-4000-8000-000000200894', '00000000-0000-4000-8000-000000100009', 84, 235180, 235660, 'Asshole.', '混蛋。', 'B1', array['asshole']::text[]),
  ('00000000-0000-4000-8000-000000200895', '00000000-0000-4000-8000-000000100009', 85, 236020, 238700, 'Hey, this is why this is perfect.', '嘿，这正是为什么这事再完美不过。', 'B1', array['perfect']::text[]),
  ('00000000-0000-4000-8000-000000200896', '00000000-0000-4000-8000-000000100009', 86, 239100, 241620, 'You''re not interested in me, and I''m not interested in the relationship.', '你对我没兴趣，我也对恋爱关系没兴趣。', 'B1', array['you''re', 'interested', 'relationship']::text[]),
  ('00000000-0000-4000-8000-000000200897', '00000000-0000-4000-8000-000000100009', 87, 243580, 245880, 'So this arrangement is mutually beneficial.', '所以这个安排对双方都有利。', 'B1', array['arrangement', 'mutually', 'beneficial']::text[]),
  ('00000000-0000-4000-8000-000000200898', '00000000-0000-4000-8000-000000100009', 88, 246340, 247620, 'Purely transactional.', '纯粹是笔交易。', 'B1', array['purely', 'transactional']::text[]),
  ('00000000-0000-4000-8000-000000200899', '00000000-0000-4000-8000-000000100009', 89, 249060, 250340, 'So?', '所以呢？', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200900', '00000000-0000-4000-8000-000000100009', 90, 253160, 254440, 'Deal.', '成交。', 'B1', array['deal']::text[]),
  ('00000000-0000-4000-8000-000000200901', '00000000-0000-4000-8000-000000100009', 91, 275620, 278400, 'For this plan to work, we have to sell it.', '要让这个计划成功，我们就得把戏演足。', 'B1', array['plan', 'work', 'have', 'sell']::text[]),
  ('00000000-0000-4000-8000-000000200902', '00000000-0000-4000-8000-000000100009', 92, 280140, 281140, 'We''re going to be fake dating.', '我们要假装在约会。', 'B1', array['we''re', 'going', 'fake', 'dating']::text[]),
  ('00000000-0000-4000-8000-000000200903', '00000000-0000-4000-8000-000000100009', 93, 281260, 282380, 'There needs to be real kissing.', '那就得有真的接吻。', 'B1', array['there', 'needs', 'real', 'kissing']::text[]),
  ('00000000-0000-4000-8000-000000200904', '00000000-0000-4000-8000-000000100009', 94, 282560, 283320, 'Whoa, easy.', '喔，悠着点。', 'B1', array['whoa', 'easy']::text[]),
  ('00000000-0000-4000-8000-000000200905', '00000000-0000-4000-8000-000000100009', 95, 283600, 284720, 'I just met you.', '我才刚认识你。', 'B1', array['just']::text[]),
  ('00000000-0000-4000-8000-000000200906', '00000000-0000-4000-8000-000000100009', 96, 284840, 285940, 'What are we going to do, hold hands?', '不然我们要怎么办，牵牵手吗？', 'B1', array['what', 'going', 'hold', 'hands']::text[]),
  ('00000000-0000-4000-8000-000000200907', '00000000-0000-4000-8000-000000100009', 97, 286160, 287900, 'You seriously think that''s going to get Justin''s attention?', '你真觉得那样能引起贾斯汀的注意？', 'B1', array['seriously', 'think', 'that''s', 'going', 'justin''s', 'attention']::text[]),
  ('00000000-0000-4000-8000-000000200908', '00000000-0000-4000-8000-000000100009', 98, 288320, 289000, 'Is he looking?', '他在看吗？', 'B1', array['looking']::text[]),
  ('00000000-0000-4000-8000-000000200909', '00000000-0000-4000-8000-000000100009', 99, 289920, 290320, 'No.', '没有。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200910', '00000000-0000-4000-8000-000000100009', 100, 295720, 296640, 'He''s looking now.', '他现在在看了。', 'B1', array['he''s', 'looking']::text[]),
  ('00000000-0000-4000-8000-000000200911', '00000000-0000-4000-8000-000000100009', 101, 300480, 302520, 'This won''t make your friendship weird at all?', '这一点都不会让你们的友谊变尴尬吗？', 'B1', array['won''t', 'make', 'friendship', 'weird']::text[]),
  ('00000000-0000-4000-8000-000000200912', '00000000-0000-4000-8000-000000100009', 102, 303580, 306840, 'Convince anyone that we''re hooking up, you can''t blush whenever I come near you.', '想让人相信我们在搞暧昧，你就不能我一靠近你就脸红。', 'B1', array['convince', 'anyone', 'we''re', 'hooking', 'can''t', 'blush']::text[]),
  ('00000000-0000-4000-8000-000000200913', '00000000-0000-4000-8000-000000100009', 103, 306920, 308180, 'Get over yourself. I don''t blush.', '别自作多情了。我才不脸红。', 'B1', array['over', 'yourself', 'don''t', 'blush']::text[]),
  ('00000000-0000-4000-8000-000000200914', '00000000-0000-4000-8000-000000100009', 104, 308440, 309140, 'Oh, yeah?', '哦，是吗？', 'B1', array['yeah']::text[]),
  ('00000000-0000-4000-8000-000000200915', '00000000-0000-4000-8000-000000100009', 105, 312000, 313440, 'See? Nothing.', '看到没？什么反应都没有。', 'B1', array['nothing']::text[]),
  ('00000000-0000-4000-8000-000000200916', '00000000-0000-4000-8000-000000100009', 106, 313980, 314500, 'Not bad.', '还不赖。', 'B1', array[]::text[]),
  ('00000000-0000-4000-8000-000000200917', '00000000-0000-4000-8000-000000100009', 107, 318960, 321100, 'It''s me and you on the Bruins. That''s the dream, right?', '我和你一起进棕熊队。那才是梦想，对吧？', 'B1', array['it''s', 'bruins', 'that''s', 'dream', 'right']::text[]),
  ('00000000-0000-4000-8000-000000200918', '00000000-0000-4000-8000-000000100009', 108, 321860, 323260, 'Garrett Graham doesn''t do girlfriends.', '加勒特·格雷厄姆从不谈女朋友。', 'B1', array['garrett', 'graham', 'doesn''t', 'girlfriends']::text[]),
  ('00000000-0000-4000-8000-000000200919', '00000000-0000-4000-8000-000000100009', 109, 323720, 324660, 'What''s really going on?', '到底是怎么回事？', 'B1', array['what''s', 'really', 'going']::text[]),
  ('00000000-0000-4000-8000-000000200920', '00000000-0000-4000-8000-000000100009', 110, 326000, 327340, 'Oh, my God. Justin''s here.', '哦，我的天。贾斯汀来了。', 'B1', array['justin''s', 'here']::text[]),
  ('00000000-0000-4000-8000-000000200921', '00000000-0000-4000-8000-000000100009', 111, 327560, 328780, 'Be cool. You''re with me.', '淡定点。你和我在一起呢。', 'B1', array['cool', 'you''re']::text[]),
  ('00000000-0000-4000-8000-000000200922', '00000000-0000-4000-8000-000000100010', 1, 1020, 3420, 'He is not just some random guy I want to hook up with.', '他不是什么我随便想上的路人。', 'B1', array['just', 'some', 'random', 'want', 'hook']::text[]),
  ('00000000-0000-4000-8000-000000200923', '00000000-0000-4000-8000-000000100010', 2, 3580, 5780, 'He is a talented musician who I respect.', '他是一位我敬重的、才华横溢的音乐人。', 'B1', array['talented', 'musician', 'respect']::text[]),
  ('00000000-0000-4000-8000-000000200924', '00000000-0000-4000-8000-000000100010', 3, 6900, 8820, 'Why don''t you tell me what you think the song''s about?', '不如你来告诉我，你觉得这首歌写的是什么？', 'B1', array['don''t', 'tell', 'what', 'think', 'song''s', 'about']::text[]),
  ('00000000-0000-4000-8000-000000200925', '00000000-0000-4000-8000-000000100010', 4, 9060, 11240, 'Like, being in love with someone who doesn''t see you.', '比如，爱上一个看不见你的人。', 'B1', array['like', 'being', 'love', 'someone', 'doesn''t']::text[]),
  ('00000000-0000-4000-8000-000000200926', '00000000-0000-4000-8000-000000100010', 5, 13240, 14080, 'She''s not my girlfriend.', '她不是我女朋友。', 'B1', array['she''s', 'girlfriend']::text[]),
  ('00000000-0000-4000-8000-000000200927', '00000000-0000-4000-8000-000000100010', 6, 14460, 15840, 'But you clearly want her to be.', '但你显然希望她是。', 'B1', array['clearly', 'want']::text[]),
  ('00000000-0000-4000-8000-000000200928', '00000000-0000-4000-8000-000000100010', 7, 21700, 23760, 'You''re not taking us this seriously.', '你没把我们这场比赛当回事。', 'B1', array['you''re', 'taking', 'seriously']::text[]),
  ('00000000-0000-4000-8000-000000200929', '00000000-0000-4000-8000-000000100010', 8, 24280, 25680, 'Watch the player, not the punk.', '盯着真正的球员，别管那个小混混。', 'B1', array['watch', 'player', 'punk']::text[]),
  ('00000000-0000-4000-8000-000000200930', '00000000-0000-4000-8000-000000100010', 9, 26120, 27300, 'What the hell does that mean?', '这他妈到底什么意思？', 'B1', array['what', 'hell', 'does', 'mean']::text[]),
  ('00000000-0000-4000-8000-000000200931', '00000000-0000-4000-8000-000000100010', 10, 27540, 29040, 'It means, trust me.', '意思是，相信我。', 'B1', array['means', 'trust']::text[]),
  ('00000000-0000-4000-8000-000000200932', '00000000-0000-4000-8000-000000100010', 11, 46060, 48720, 'I''m dancing with myself.', '我独自一人起舞。', 'B1', array['dancing', 'myself']::text[]),
  ('00000000-0000-4000-8000-000000200933', '00000000-0000-4000-8000-000000100010', 12, 49100, 51920, 'So let''s sink another drink.', '那就再灌下一杯吧。', 'B1', array['let''s', 'sink', 'another', 'drink']::text[]),
