  ('00000000-0000-4000-8000-000000200937', '00000000-0000-4000-8000-000000100010', 16, 102160, 105540, 'I''ve looked all over the world', '我找遍了全世界', 'B1', array['i''ve', 'looked', 'over', 'world']::text[]),
  ('00000000-0000-4000-8000-000000200938', '00000000-0000-4000-8000-000000100010', 17, 105540, 108660, 'And there''s every type of girl', '形形色色的女孩都有', 'B1', array['there''s', 'every', 'type', 'girl']::text[]),
