-- Seed the personal V1 workspace with the real local mock episode.
-- Run after supabase/schema.sql. This removes the earlier placeholder shows.

begin;

delete from public.series
where id in ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000002')
   or title in ('雨巷公寓', '九号站台');

on conflict (id) do update set
  title = excluded.title,
  original_title = excluded.original_title,
  description = excluded.description,
  cover_url = excluded.cover_url,
  difficulty = excluded.difficulty,
  genre = excluded.genre,
  status = excluded.status;

on conflict (series_id, season_number, episode_number) do update set
  title = excluded.title,
  description = excluded.description,
  media_url = excluded.media_url,
  duration_seconds = excluded.duration_seconds,
  status = excluded.status;

delete from public.subtitle_lines
where episode_id in ('00000000-0000-4000-8000-000000100001', '00000000-0000-4000-8000-000000100002', '00000000-0000-4000-8000-000000100003', '00000000-0000-4000-8000-000000100004', '00000000-0000-4000-8000-000000100005', '00000000-0000-4000-8000-000000100006', '00000000-0000-4000-8000-000000100007', '00000000-0000-4000-8000-000000100008', '00000000-0000-4000-8000-000000100009', '00000000-0000-4000-8000-000000100010');

on conflict (episode_id, line_index) do update set
  start_ms = excluded.start_ms,
  end_ms = excluded.end_ms,
  english_text = excluded.english_text,
  chinese_text = excluded.chinese_text,
  difficulty = excluded.difficulty,
  keywords = excluded.keywords;

on conflict (word) do update set
  phonetic = excluded.phonetic,
  translation = excluded.translation,
  definition = excluded.definition,
  pos = excluded.pos,
  frq = excluded.frq;

commit;
